/**
 * Teams API Route - List and Create
 *
 * GET  /api/noc/teams - List all teams
 * POST /api/noc/teams - Create new team
 */

import { NextRequest, NextResponse } from 'next/server';
import { createLogger } from '@/lib/logger';
import {
  listTeams,
  createTeam,
  getTeamsForDropdown,
} from '@/modules/noc/services/teamService';
import type { CreateTeamPayload, TeamFilters } from '@/modules/noc/types/team';

const logger = createLogger('maintenance:api:teams');

/**
 * GET /api/noc/teams
 *
 * Query params:
 * - team_type: Filter by team type
 * - contractor_id: Filter by contractor
 * - is_active: Filter by active status
 * - search: Search by name/description
 * - dropdown: If 'true', returns simplified format for dropdowns
 */
export async function GET(req: NextRequest) {
  try {
    const { searchParams } = new URL(req.url);
    const isDropdown = searchParams.get('dropdown') === 'true';

    if (isDropdown) {
      const teams = await getTeamsForDropdown();
      return NextResponse.json({
        success: true,
        data: teams,
        meta: { timestamp: new Date().toISOString() },
      });
    }

    const filters: TeamFilters = {};

    if (searchParams.has('team_type')) {
      filters.team_type = searchParams.get('team_type')!;
    }
    if (searchParams.has('contractor_id')) {
      filters.contractor_id = searchParams.get('contractor_id')!;
    }
    if (searchParams.has('is_active')) {
      filters.is_active = searchParams.get('is_active') === 'true';
    }
    if (searchParams.has('search')) {
      filters.search = searchParams.get('search')!;
    }

    logger.debug('Fetching teams', { filters });

    const teams = await listTeams(filters);

    return NextResponse.json({
      success: true,
      data: teams,
      meta: { timestamp: new Date().toISOString(), count: teams.length },
    });
  } catch (error) {
    logger.error('Error fetching teams', { error });
    return NextResponse.json(
      {
        success: false,
        error: { code: 'DATABASE_ERROR', message: 'Failed to fetch teams' },
        meta: { timestamp: new Date().toISOString() },
      },
      { status: 500 }
    );
  }
}

/**
 * POST /api/noc/teams
 */
export async function POST(req: NextRequest) {
  try {
    const body: CreateTeamPayload = await req.json();

    // Validate required fields
    if (!body.name?.trim()) {
      return NextResponse.json(
        {
          success: false,
          error: { code: 'VALIDATION_ERROR', message: 'Team name is required' },
          meta: { timestamp: new Date().toISOString() },
        },
        { status: 422 }
      );
    }

    logger.info('Creating team', { name: body.name, type: body.team_type });

    const team = await createTeam(body);

    return NextResponse.json(
      {
        success: true,
        data: team,
        message: 'Team created successfully',
        meta: { timestamp: new Date().toISOString() },
      },
      { status: 201 }
    );
  } catch (error: any) {
    logger.error('Error creating team', { error });

    // Check for unique constraint violation
    if (error.message?.includes('unique') || error.code === '23505') {
      return NextResponse.json(
        {
          success: false,
          error: { code: 'DUPLICATE_ERROR', message: 'A team with this name already exists' },
          meta: { timestamp: new Date().toISOString() },
        },
        { status: 409 }
      );
    }

    return NextResponse.json(
      {
        success: false,
        error: { code: 'DATABASE_ERROR', message: 'Failed to create team' },
        meta: { timestamp: new Date().toISOString() },
      },
      { status: 500 }
    );
  }
}

/**
 * Individual Team API Route
 *
 * GET    /api/noc/teams/[id] - Get team by ID
 * PUT    /api/noc/teams/[id] - Update team
 * DELETE /api/noc/teams/[id] - Delete team (soft delete)
 */

import { NextRequest, NextResponse } from 'next/server';
import { createLogger } from '@/lib/logger';
import {
  getTeamById,
  updateTeam,
  deleteTeam,
  getTeamMembers,
} from '@/modules/noc/services/teamService';
import type { UpdateTeamPayload } from '@/modules/noc/types/team';

const logger = createLogger('maintenance:api:teams:id');

const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function isValidUUID(id: string): boolean {
  return UUID_REGEX.test(id);
}

/**
 * GET /api/noc/teams/[id]
 *
 * Query params:
 * - include_members: If 'true', includes team members
 */
export async function GET(
  req: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    const teamId = params.id;
    const { searchParams } = new URL(req.url);
    const includeMembers = searchParams.get('include_members') === 'true';

    if (!isValidUUID(teamId)) {
      return NextResponse.json(
        {
          success: false,
          error: { code: 'VALIDATION_ERROR', message: 'Invalid team ID format' },
          meta: { timestamp: new Date().toISOString() },
        },
        { status: 422 }
      );
    }

    logger.debug('Fetching team', { teamId, includeMembers });

    const team = await getTeamById(teamId);

    if (!team) {
      return NextResponse.json(
        {
          success: false,
          error: { code: 'NOT_FOUND', message: `Team with ID '${teamId}' not found` },
          meta: { timestamp: new Date().toISOString() },
        },
        { status: 404 }
      );
    }

    let members = null;
    if (includeMembers) {
      members = await getTeamMembers(teamId);
    }

    return NextResponse.json({
      success: true,
      data: {
        ...team,
        ...(members && { members }),
      },
      meta: { timestamp: new Date().toISOString() },
    });
  } catch (error) {
    logger.error('Error fetching team', { error, teamId: params.id });
    return NextResponse.json(
      {
        success: false,
        error: { code: 'DATABASE_ERROR', message: 'Failed to fetch team' },
        meta: { timestamp: new Date().toISOString() },
      },
      { status: 500 }
    );
  }
}

/**
 * PUT /api/noc/teams/[id]
 */
export async function PUT(
  req: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    const teamId = params.id;

    if (!isValidUUID(teamId)) {
      return NextResponse.json(
        {
          success: false,
          error: { code: 'VALIDATION_ERROR', message: 'Invalid team ID format' },
          meta: { timestamp: new Date().toISOString() },
        },
        { status: 422 }
      );
    }

    const body: UpdateTeamPayload = await req.json();

    if (Object.keys(body).length === 0) {
      return NextResponse.json(
