        email,
        position as role,
        department
      FROM staff
      WHERE status = 'active'
      ORDER BY first_name ASC, last_name ASC
    `;

    const users = await query<UserDropdownOption>(sql, []);
    return users;
  } catch (error) {
    logger.error('Failed to fetch users for dropdown', { error });
    throw error;
  }
}

