} from '@/types/staff.types';

/**
 * Core CRUD operations for staff management
 */
export const staffCrudService = {
  /**
   * Get all staff with optional filtering
   */
  async getAll(filter?: StaffFilter): Promise<StaffMember[]> {
    try {
      // Get all staff without filtering to avoid index requirements
      const q = query(collection(db, 'staff'), orderBy('name', 'asc'));
      const snapshot = await getDocs(q);

      let staffMembers = snapshot.docs.map((doc: any) => ({
        id: doc.id,
        ...doc.data()
      } as StaffMember));

      // Apply all filters client-side
      if (filter?.status?.length) {
        staffMembers = staffMembers.filter((staff: any) =>
          filter.status!.includes(staff.status)
        );
      }

      if (filter?.department?.length) {
        staffMembers = staffMembers.filter((staff: any) =>
          filter.department!.includes(staff.department)
        );
      }

      if (filter?.level?.length) {
        staffMembers = staffMembers.filter((staff: any) =>
          staff.level && filter.level!.includes(staff.level)
        );
      }

      if (filter?.managerId) {
        staffMembers = staffMembers.filter((staff: any) =>
          staff.managerId === filter.managerId
        );
      }

      // Apply search term filter
      if (filter?.searchTerm) {
        const searchTerm = filter.searchTerm.toLowerCase();
        staffMembers = staffMembers.filter((staff: any) =>
          staff.name.toLowerCase().includes(searchTerm) ||
          staff.email.toLowerCase().includes(searchTerm) ||
          staff.phone.includes(searchTerm) ||
          staff.employeeId.toLowerCase().includes(searchTerm) ||
          staff.position.toLowerCase().includes(searchTerm)
        );
      }

      return staffMembers;
    } catch (error) {
      log.error('Error getting staff:', { data: error }, 'staffCrudService');
      throw new Error('Failed to fetch staff');
    }
  },

  /**
   * Get staff member by ID
   */
  async getById(id: string): Promise<StaffMember | null> {
    try {
      const docRef = doc(db, 'staff', id);
      const snapshot = await getDoc(docRef);

      if (!snapshot.exists()) {
        return null;
      }

      return { 
        id: snapshot.id, 
        ...snapshot.data() 
      } as StaffMember;
    } catch (error) {
      log.error('Error getting staff member:', { data: error }, 'staffCrudService');
      throw new Error('Failed to fetch staff member');
    }
  },

  /**
   * Create new staff member
   */
  async create(data: StaffFormData): Promise<string> {
    try {
      const now = Timestamp.now();

      // Build staff data without undefined values
      const staffData: any = {
        ...data,

        // Convert dates
        startDate: Timestamp.fromDate(data.startDate),

        // Set default values
        alternativePhone: data.alternativePhone || '',
        managerName: '',
        reportsTo: data.managerId || '',
        specializations: [],
        emergencyContactName: data.emergencyContactName || '',
        emergencyContactPhone: data.emergencyContactPhone || '',
        salaryGrade: data.salaryGrade || '',
        hourlyRate: data.hourlyRate || 0,

        // Initialize arrays and metrics
        certifications: [],
        activeProjectIds: [],
        currentProjectCount: 0,
        totalProjectsCompleted: 0,
        averageProjectRating: 0,
        onTimeCompletionRate: 0,
        assignedEquipment: [],
        vehicleAssigned: '',
        toolsAssigned: [],
        trainingRecords: [],
        performanceNotes: '',
        profilePhotoUrl: '',
        bio: '',

        // Set audit fields
        createdAt: now,
        updatedAt: now,
        createdBy: 'current-user', // TODO: Get from auth context
        lastModifiedBy: 'current-user',
      };

      // Only add endDate if it exists
      if (data.endDate) {
        staffData.endDate = Timestamp.fromDate(data.endDate);
      }

      // Remove any undefined values that Firebase doesn't accept
      Object.keys(staffData).forEach(key => {
        if (staffData[key] === undefined) {
          delete staffData[key];
        }
      });

      const docRef = await addDoc(collection(db, 'staff'), staffData);
      return docRef.id;
    } catch (error) {
      log.error('Error creating staff member:', { data: error }, 'staffCrudService');
      throw new Error('Failed to create staff member');
    }
  },

  /**
   * Update staff member
   */
  async update(id: string, data: Partial<StaffFormData>): Promise<void> {
    try {
      const docRef = doc(db, 'staff', id);
      const updateData: any = {
        ...data,
        updatedAt: Timestamp.now(),
        lastModifiedBy: 'current-user', // TODO: Get from auth context
      };

      // Convert dates if provided
      if (data.startDate) {
        updateData.startDate = Timestamp.fromDate(data.startDate);
      }
      if (data.endDate) {
        updateData.endDate = Timestamp.fromDate(data.endDate);
      }

      await updateDoc(docRef, updateData);
    } catch (error) {
      log.error('Error updating staff member:', { data: error }, 'staffCrudService');
      throw new Error('Failed to update staff member');
    }
  },

  /**
   * Delete staff member
   */
  async delete(id: string): Promise<void> {
    try {
      // Check if staff member has active projects
      const projectsQuery = query(
        collection(db, 'projectAssignments'),
        where('staffId', '==', id),
        where('status', '==', 'active')
      );
      const projectsSnapshot = await getDocs(projectsQuery);

      if (!projectsSnapshot.empty) {
        throw new Error('Cannot delete staff member with active project assignments');
      }

      await deleteDoc(doc(db, 'staff', id));
    } catch (error) {
      log.error('Error deleting staff member:', { data: error }, 'staffCrudService');
      throw new Error('Failed to delete staff member');
    }
  },

  /**
   * Subscribe to staff changes
   */
  subscribeToStaff(
    callback: (staff: StaffMember[]) => void,
    filter?: StaffFilter
  ): Unsubscribe {
    // Get all staff to avoid index requirements
    const q = query(collection(db, 'staff'), orderBy('name', 'asc'));

    return onSnapshot(q, (snapshot: any) => {
      let staffMembers = snapshot.docs.map((doc: any) => ({
        id: doc.id,
        ...doc.data()
      } as StaffMember));

      // Apply filters client-side
      if (filter?.status?.length) {
        staffMembers = staffMembers.filter((staff: any) =>
          filter.status!.includes(staff.status)
        );
      }

      if (filter?.department?.length) {
        staffMembers = staffMembers.filter((staff: any) =>
          filter.department!.includes(staff.department)
        );
      }

      if (filter?.level?.length) {
        staffMembers = staffMembers.filter((staff: any) =>
          staff.level && filter.level!.includes(staff.level)
        );
      }

      if (filter?.searchTerm) {
        const searchTerm = filter.searchTerm.toLowerCase();
        staffMembers = staffMembers.filter((staff: any) =>
          staff.name.toLowerCase().includes(searchTerm) ||
          staff.email.toLowerCase().includes(searchTerm) ||
          staff.phone.includes(searchTerm) ||
          staff.employeeId.toLowerCase().includes(searchTerm) ||
          staff.position.toLowerCase().includes(searchTerm)
        );
      }

      callback(staffMembers);
    });
  },

  /**
   * Subscribe to single staff member changes
   */
  subscribeToStaffMember(
    staffId: string,
    callback: (staff: StaffMember | null) => void
  ): Unsubscribe {
    const docRef = doc(db, 'staff', staffId);

    return onSnapshot(docRef, (snapshot: any) => {
      if (snapshot.exists()) {
        const staff = {
          id: snapshot.id,
          ...snapshot.data()
        } as StaffMember;
        callback(staff);
      } else {
        callback(null);
      }
    });
  }
};

/**
 * DR Lookup Service
 *
 * Queries SOW module for DR (Drop) details including project, zone, pole, and PON information.
 *
 * Features:
 * - Lookup DR from drops table in SOW module
 * - Returns project, zone, pole, PON details
 * - In-memory caching to reduce database queries
 * - Comprehensive error handling
 *
 * 🟢 WORKING: Production-ready DR lookup service with caching
 */

import { queryOne } from '../utils/db';
import { DRLookupResult, DRLookupData } from '../types/ticket';
import { createLogger } from '@/lib/logger';

const logger = createLogger({ module: 'drLookupService' });

/**
 * In-memory cache for DR lookup results
 * Key: DR number
 * Value: DRLookupData
 */
const drCache = new Map<string, DRLookupData>();

/**
 * Lookup DR number in SOW module and return complete details
 * 🟢 WORKING: Queries drops table and enriches with project data
 *
 * @param drNumber - The DR (drop) number to lookup
 * @returns DRLookupResult with success flag and data or error
 */
export async function lookupDR(drNumber: string): Promise<DRLookupResult> {
  try {
    // Validate input
    const trimmedDR = drNumber.trim();
    if (!trimmedDR) {
      return {
        success: false,
        data: null,
        error: 'DR number is required'
      };
    }

    // Check cache first
    const cachedResult = drCache.get(trimmedDR);
    if (cachedResult) {
      logger.debug('DR lookup cache hit', { drNumber: trimmedDR });
      return {
        success: true,
        data: cachedResult
      };
    }

    logger.info('Looking up DR number in SOW module', { drNumber: trimmedDR });

    // Query onemap.drops table for DR details (with project join)
    const drData = await queryOne<{
      dr_number: string;
      pole_number: string | null;
      project_id: string | null;
      pon_code: string | null;
      zone_code: string | null;
      address: string | null;
      latitude: number | null;
      longitude: number | null;
      current_status: string | null;
      project_name: string | null;
      project_code: string | null;
    }>(
      `SELECT
        d.dr_number,
        d.pole_number,
        d.project_id::text as project_id,
        d.pon_code,
        d.zone_code,
        NULLIF(d.address, 'NULL') as address,
        d.latitude::float as latitude,
        d.longitude::float as longitude,
        d.current_status,
        p.project_name,
        p.project_code
      FROM onemap.drops d
      LEFT JOIN onemap.projects p ON d.project_id = p.id
      WHERE UPPER(d.dr_number) = UPPER($1)`,
      [trimmedDR]
    );

    // Check if DR was found
    if (!drData || !drData.dr_number) {
      logger.warn('DR number not found', { drNumber: trimmedDR });
      return {
        success: false,
        data: null,
        error: 'DR number not found'
      };
    }

    // Parse zone and pon codes to numbers
    const zoneNumber = drData.zone_code ? parseInt(drData.zone_code, 10) : null;
    const ponNumber = drData.pon_code ? parseInt(drData.pon_code, 10) : null;

    // Initialize result data with DR information (project already joined)
    const resultData: DRLookupData = {
      dr_number: drData.dr_number,
      pole_number: drData.pole_number,
      pon_number: isNaN(ponNumber as number) ? null : ponNumber,
      zone_number: isNaN(zoneNumber as number) ? null : zoneNumber,
      project_id: drData.project_id,
      project_name: drData.project_name,
      project_code: drData.project_code,
      address: drData.address,
      latitude: drData.latitude,
      longitude: drData.longitude,
      municipality: null, // Not in onemap schema
      cable_type: null,   // Not in onemap schema
      cable_length: null, // Not in onemap schema
      status: drData.current_status
    };

    logger.debug('DR lookup successful', {
      drNumber: trimmedDR,
      projectCode: drData.project_code,
      projectName: drData.project_name
    });

    // Cache the result
    drCache.set(trimmedDR, resultData);
    logger.debug('DR lookup result cached', { drNumber: trimmedDR });

    return {
      success: true,
      data: resultData
    };
  } catch (error) {
    logger.error('Failed to lookup DR number', {
      error,
      drNumber: drNumber
    });

    return {
      success: false,
      data: null,
      error: `Failed to lookup DR number: ${error instanceof Error ? error.message : 'Unknown error'}`
    };
  }
}

/**
 * Get DR data from cache without querying database
 * 🟢 WORKING: Cache retrieval utility
 *
 * @param drNumber - The DR number to retrieve from cache
 * @returns Cached DRLookupData or null if not in cache
 */
export function getDRFromCache(drNumber: string): DRLookupData | null {
  const trimmedDR = drNumber.trim();
  return drCache.get(trimmedDR) || null;
}

/**
 * Clear all cached DR lookup results
 * 🟢 WORKING: Cache management utility
 *
 * Use this to invalidate cache when DR data changes
 */
export function clearDRCache(): void {
  drCache.clear();
  logger.info('DR lookup cache cleared');
}

/**
 * Clear specific DR from cache
 * 🟢 WORKING: Selective cache invalidation
 *
 * @param drNumber - The DR number to remove from cache
 */
export function clearDRFromCache(drNumber: string): void {
  const trimmedDR = drNumber.trim();
  const deleted = drCache.delete(trimmedDR);

  if (deleted) {
    logger.debug('DR removed from cache', { drNumber: trimmedDR });
  }
}

/**
 * Get cache statistics
 * 🟢 WORKING: Cache monitoring utility
 *
 * @returns Cache size and statistics
 */
export function getDRCacheStats(): {
  size: number;
  entries: string[];
} {
  return {
    size: drCache.size,
    entries: Array.from(drCache.keys())
  };
}

/**
 * Project Dashboard API
 * GET /api/projects/[projectId]/dashboard
 *
 * Returns aggregated metrics from all modules for a project
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { withAuth } from '@/lib/auth';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';

const getSql = () => neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const { projectId } = req.query;

  if (!projectId || typeof projectId !== 'string') {
    return apiResponse.validationError(res, { projectId: 'Project ID is required' });
  }

  try {
    const sql = getSql();

    // Get aggregated data from the dashboard view
    const dashboardData = await sql`
      SELECT *
      FROM v_project_dashboard
      WHERE id = ${projectId}
    `;

    if (!dashboardData || dashboardData.length === 0) {
      return apiResponse.notFound(res, 'Project', projectId);
    }

    const project = dashboardData[0];

    // Format response with clear categories
    const response = {
      project: {
        id: project.id,
        code: project.project_code,
        name: project.project_name,
        status: project.status,
        progress: project.progress || 0,
        startDate: project.start_date,
        endDate: project.end_date,
        clientId: project.client_id,
        clientName: project.client_name,
      },
      budget: {
        total: Number(project.total_budget) || Number(project.budget) || 0,
        committed: Number(project.committed_amount) || 0,
        actual: Number(project.budget_actual_amount) || Number(project.actual_cost) || 0,
        available: Number(project.available_budget) || 0,
        health: project.budget_health || 'unknown',
      },
      team: {
        staffCount: Number(project.staff_count) || 0,
        contractorCount: Number(project.contractor_count) || 0,
        primaryManager: project.primary_manager_name || null,
      },
      hs: {
        latestScore: project.latest_hs_score ? Number(project.latest_hs_score) : null,
        lastAuditDate: project.last_audit_date || null,
        complianceStatus: project.latest_hs_score
          ? project.latest_hs_score >= 80 ? 'compliant' : 'non-compliant'
          : 'unknown',
      },
      maintenance: {
        openTickets: Number(project.open_tickets) || 0,
        resolvedThisMonth: Number(project.resolved_this_month) || 0,
      },
      procurement: {
        pendingPOs: Number(project.pending_pos) || 0,
        pendingRFQs: Number(project.pending_rfqs) || 0,
        totalPoValue: Number(project.total_po_value) || 0,
      },
    };

    return apiResponse.success(res, response);
  } catch (error) {
    log.error('Error fetching project dashboard', { error, projectId });
    return apiResponse.internalError(res, error as Error);
  }
}

export default withAuth(handler);

