/**
 * Result from WA photo serial extraction
 */
export interface WaPhotoExtractionResult {
  success: boolean;
  ontSerial: string | null;
  upsSerial: string | null;
  confidence: number;
  ontConfidence: number;
  upsConfidence: number;
  processingTimeMs: number;
  error?: string;
