import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth } from '@/lib/auth';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  try {
    // Run all metric queries in parallel
    // Use Promise.allSettled to identify which query fails
    const results = await Promise.allSettled([
      // Total active projects
      sql`SELECT
        COUNT(*)::int as total_projects,
        COUNT(*) FILTER (WHERE status = 'active')::int as active_projects
        FROM projects`,

      // BOQ value
      sql`SELECT
        COALESCE(SUM(total_value), 0)::numeric as total_boq_value,
        COUNT(*)::int as total_boqs,
        COUNT(*) FILTER (WHERE status IN ('draft', 'review'))::int as active_boqs
        FROM boqs`,

      // RFQ metrics
      sql`SELECT
        COUNT(*)::int as total_rfqs,
        COUNT(*) FILTER (WHERE status = 'open')::int as active_rfqs,
        COUNT(*) FILTER (WHERE status = 'closed')::int as closed_rfqs
        FROM rfqs`,

      // Purchase order metrics
      sql`SELECT
        COUNT(*)::int as total_pos,
        COUNT(*) FILTER (WHERE status = 'pending')::int as pending_pos,
        COUNT(*) FILTER (WHERE status = 'approved')::int as approved_pos,
        COALESCE(SUM(total_amount), 0)::numeric as total_po_value
        FROM purchase_orders`,

      // Stock metrics
      sql`SELECT
        COUNT(*)::int as total_stock_items,
        COUNT(*) FILTER (WHERE qty_available <= min_stock_level AND min_stock_level > 0)::int as low_stock_items
        FROM stock_items`,

      // Supplier metrics
      sql`SELECT
        COUNT(DISTINCT id)::int as total_suppliers
        FROM suppliers WHERE is_active = true`,

      // Pending approvals
      sql`SELECT
        COUNT(*)::int as pending_approvals
        FROM purchase_orders WHERE status = 'pending'`,

      // Per-project summaries (top 20 active projects)
      sql`SELECT
        p.id,
        p.project_name as name,
        p.project_code as code,
        p.status,
        COALESCE(boq.total_value, 0)::numeric as boq_value,
        COALESCE(rfq.active_count, 0)::int as active_rfqs,
        COALESCE(po.pending_count, 0)::int as pending_pos,
        COALESCE(stock_alerts.low_count, 0)::int as stock_alerts,
        p.actual_progress as completion_percentage
      FROM projects p
      LEFT JOIN LATERAL (
        SELECT SUM(total_value) as total_value
        FROM boqs WHERE project_id = p.id::text
      ) boq ON true
      LEFT JOIN LATERAL (
        SELECT COUNT(*) as active_count
        FROM rfqs WHERE project_id = p.id::text AND status = 'open'
      ) rfq ON true
      LEFT JOIN LATERAL (
        SELECT COUNT(*) as pending_count
        FROM purchase_orders WHERE project_id = p.id::text AND status = 'pending'
      ) po ON true
      LEFT JOIN LATERAL (
        SELECT COUNT(*) as low_count
        FROM stock_items WHERE qty_available <= min_stock_level AND min_stock_level > 0
      ) stock_alerts ON true
      WHERE p.status = 'active'
      ORDER BY p.project_name
      LIMIT 20`
    ]);

    // Check for failures and log them
    const failedQueries = results
      .map((r, i) => r.status === 'rejected' ? { index: i, reason: String(r.reason) } : null)
      .filter(Boolean);

    if (failedQueries.length > 0) {
      log.error('Aggregate metrics: some queries failed', { data: failedQueries }, 'procurement/aggregate-metrics');
    }

    // Extract values (default to empty array on failure)
    const getValue = (idx: number) => results[idx]?.status === 'fulfilled' ? results[idx].value : [];
    const projectCounts = getValue(0);
    const boqMetrics = getValue(1);
    const rfqMetrics = getValue(2);
    const poMetrics = getValue(3);
    const stockMetrics = getValue(4);
    const supplierMetrics = getValue(5);
    const approvalMetrics = getValue(6);
    const projectSummaries = getValue(7);

    const metrics = {
      totalProjects: projectCounts[0]?.total_projects || 0,
      activeProjects: projectCounts[0]?.active_projects || 0,
      totalBOQValue: Number(boqMetrics[0]?.total_boq_value || 0),
      totalBOQs: boqMetrics[0]?.total_boqs || 0,
      activeBOQs: boqMetrics[0]?.active_boqs || 0,
      totalActiveRFQs: rfqMetrics[0]?.active_rfqs || 0,
      totalRFQs: rfqMetrics[0]?.total_rfqs || 0,
      closedRFQs: rfqMetrics[0]?.closed_rfqs || 0,
      totalPurchaseOrders: poMetrics[0]?.total_pos || 0,
      pendingPOs: poMetrics[0]?.pending_pos || 0,
      approvedPOs: poMetrics[0]?.approved_pos || 0,
      totalPOValue: Number(poMetrics[0]?.total_po_value || 0),
      totalStockItems: stockMetrics[0]?.total_stock_items || 0,
      lowStockItems: stockMetrics[0]?.low_stock_items || 0,
      totalSuppliers: supplierMetrics[0]?.total_suppliers || 0,
      pendingApprovals: approvalMetrics[0]?.pending_approvals || 0,
    };

    const summaries = projectSummaries.map((p: Record<string, unknown>) => ({
      id: p.id,
      name: p.name,
      code: p.code,
      status: p.status,
      boqValue: Number(p.boq_value || 0),
      activeRFQs: p.active_rfqs || 0,
      pendingPOs: p.pending_pos || 0,
      stockAlerts: p.stock_alerts || 0,
      completionPercentage: p.completion_percentage || 0,
    }));

    return apiResponse.success(res, {
      metrics,
      projectSummaries: summaries,
    });
  } catch (error) {
    log.error('Failed to fetch aggregate metrics', { data: error }, 'procurement/aggregate-metrics');
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

/**
 * Procurement Reports Data API
 * Returns real spend-by-category and cycle-time metrics from the database
 */
import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth } from '@/lib/auth';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  try {
    const results = await Promise.allSettled([
      // Spend by category from BOQ items (most populated source)
      sql`SELECT
        COALESCE(NULLIF(TRIM(bi.category), ''), 'Uncategorized') as category,
        COUNT(*)::int as item_count,
        COALESCE(SUM(bi.total_price), 0)::numeric as total_spend
      FROM boq_items bi
      JOIN boqs b ON bi.boq_id = b.id
      WHERE b.status != 'archived'
      GROUP BY COALESCE(NULLIF(TRIM(bi.category), ''), 'Uncategorized')
      ORDER BY total_spend DESC`,

      // Total BOQ spend (for percentage calculation)
      sql`SELECT COALESCE(SUM(bi.total_price), 0)::numeric as grand_total
      FROM boq_items bi
      JOIN boqs b ON bi.boq_id = b.id
      WHERE b.status != 'archived'`,

      // Cycle time: Requisition → RFQ (avg days)
      sql`SELECT
        COALESCE(AVG(EXTRACT(DAY FROM (r.created_at - pr.created_at))), 0)::numeric as avg_days,
        COALESCE(MIN(EXTRACT(DAY FROM (r.created_at - pr.created_at))), 0)::int as min_days,
        COALESCE(MAX(EXTRACT(DAY FROM (r.created_at - pr.created_at))), 0)::int as max_days,
        COUNT(*)::int as sample_count
      FROM rfqs r
      JOIN purchase_requisitions pr ON r.requisition_id = pr.id
      WHERE r.requisition_id IS NOT NULL`,

      // Cycle time: RFQ → PO (avg days)
      sql`SELECT
        COALESCE(AVG(EXTRACT(DAY FROM (po.created_at - r.created_at))), 0)::numeric as avg_days,
        COALESCE(MIN(EXTRACT(DAY FROM (po.created_at - r.created_at))), 0)::int as min_days,
        COALESCE(MAX(EXTRACT(DAY FROM (po.created_at - r.created_at))), 0)::int as max_days,
        COUNT(*)::int as sample_count
      FROM purchase_orders po
      JOIN rfqs r ON po.rfq_id = r.id
      WHERE po.rfq_id IS NOT NULL`,

      // Cycle time: PO → Delivery (avg days)
      sql`SELECT
        COALESCE(AVG(EXTRACT(DAY FROM (grn.delivery_date - po.created_at))), 0)::numeric as avg_days,
        COALESCE(MIN(EXTRACT(DAY FROM (grn.delivery_date - po.created_at))), 0)::int as min_days,
        COALESCE(MAX(EXTRACT(DAY FROM (grn.delivery_date - po.created_at))), 0)::int as max_days,
        COUNT(*)::int as sample_count
      FROM goods_receipt_notes grn
      JOIN purchase_orders po ON grn.purchase_order_id = po.id
      WHERE grn.delivery_date IS NOT NULL
        AND grn.status = 'completed'`,

      // Cycle time: GRN processing (delivery_date to created_at of GRN)
      sql`SELECT
        COALESCE(AVG(ABS(EXTRACT(DAY FROM (grn.created_at - grn.delivery_date)))), 0)::numeric as avg_days,
        COALESCE(MIN(ABS(EXTRACT(DAY FROM (grn.created_at - grn.delivery_date)))), 0)::int as min_days,
        COALESCE(MAX(ABS(EXTRACT(DAY FROM (grn.created_at - grn.delivery_date)))), 0)::int as max_days,
        COUNT(*)::int as sample_count
      FROM goods_receipt_notes grn
      WHERE grn.delivery_date IS NOT NULL
        AND grn.status = 'completed'`,

      // Overall end-to-end cycle time (PO creation to GRN completion)
      sql`SELECT
        COALESCE(AVG(EXTRACT(DAY FROM (grn.delivery_date - po.created_at))), 0)::numeric as avg_total_days
      FROM goods_receipt_notes grn
      JOIN purchase_orders po ON grn.purchase_order_id = po.id
      WHERE grn.delivery_date IS NOT NULL
        AND grn.status = 'completed'`,
    ]);

    const failedQueries = results
      .map((r, i) => r.status === 'rejected' ? { index: i, reason: String(r.reason) } : null)
      .filter(Boolean);

    if (failedQueries.length > 0) {
      log.error('Reports data: some queries failed', { data: failedQueries }, 'procurement/reports-data');
    }

    const getValue = (idx: number) => results[idx]?.status === 'fulfilled' ? results[idx].value : [];

    const spendRows = getValue(0);
    const grandTotalRow = getValue(1);
    const reqToRfq = getValue(2);
    const rfqToPo = getValue(3);
    const poToDelivery = getValue(4);
    const grnProcessing = getValue(5);
    const overallCycle = getValue(6);

    const grandTotal = Number(grandTotalRow[0]?.grand_total || 0);

    // Format spend by category with real percentages
    const spendByCategory = spendRows.map((row: Record<string, unknown>) => {
      const amount = Number(row.total_spend || 0);
      return {
        category: row.category as string,
        amount,
        percentage: grandTotal > 0 ? Math.round((amount / grandTotal) * 100) : 0,
        itemCount: Number(row.item_count || 0),
      };
    });

    // Build cycle metrics from real timestamp diffs
    const formatCycleRow = (row: Record<string, unknown>[], stage: string) => {
      const r = row[0] || {};
      const avg = Math.round(Number(r.avg_days || 0));
      return {
        stage,
        avgDays: avg,
        minDays: Number(r.min_days || 0),
        maxDays: Number(r.max_days || 0),
        sampleCount: Number(r.sample_count || 0),
      };
    };

    const cycleMetrics = [
      formatCycleRow(reqToRfq, 'Requisition to RFQ'),
      formatCycleRow(rfqToPo, 'RFQ to Purchase Order'),
      formatCycleRow(poToDelivery, 'PO to Delivery'),
      formatCycleRow(grnProcessing, 'GRN Processing'),
    ];

    const avgTotalCycleDays = Math.round(Number(overallCycle[0]?.avg_total_days || 0));

    return apiResponse.success(res, {
      spendByCategory,
      cycleMetrics,
      avgTotalCycleDays,
    });
  } catch (error) {
    log.error('Failed to fetch reports data', { data: error }, 'procurement/reports-data');
    return apiResponse.internalError(res, error);
  }
}

