/**
 * GET /api/procurement/boq-spend-summary
 * Cross-project BOQ spend summary — shows spend vs BOQ value for all projects with active BOQs.
 * "Confirmed" = POs with status received/partially_received/invoiced/paid.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, ['GET']);
  }

  const { projectId, dateFrom, dateTo } = req.query;
  const from = typeof dateFrom === 'string' ? dateFrom : null;
  const to = typeof dateTo === 'string' ? dateTo : null;

  // If projectId provided, return PO transactions for that project
  if (projectId && typeof projectId === 'string') {
    try {
      let rows;
      if (from && to) {
        rows = await sql`
          SELECT po.id, po.external_po_number, po.status, po.order_date, s.name as supplier_name,
            COALESCE(SUM(poi.total_price), 0)::numeric as total_amount, COUNT(poi.id) as item_count
          FROM purchase_orders po LEFT JOIN suppliers s ON s.id = po.supplier_id
            LEFT JOIN purchase_order_items poi ON poi.purchase_order_id = po.id
          WHERE po.project_id::text = ${projectId}::text AND po.status NOT IN ('draft', 'cancelled')
            AND po.order_date >= ${from}::date AND po.order_date <= ${to}::date
          GROUP BY po.id, po.external_po_number, po.status, po.order_date, s.name
          ORDER BY po.order_date DESC NULLS LAST`;
      } else if (from) {
        rows = await sql`
          SELECT po.id, po.external_po_number, po.status, po.order_date, s.name as supplier_name,
            COALESCE(SUM(poi.total_price), 0)::numeric as total_amount, COUNT(poi.id) as item_count
          FROM purchase_orders po LEFT JOIN suppliers s ON s.id = po.supplier_id
            LEFT JOIN purchase_order_items poi ON poi.purchase_order_id = po.id
          WHERE po.project_id::text = ${projectId}::text AND po.status NOT IN ('draft', 'cancelled')
            AND po.order_date >= ${from}::date
          GROUP BY po.id, po.external_po_number, po.status, po.order_date, s.name
          ORDER BY po.order_date DESC NULLS LAST`;
      } else if (to) {
        rows = await sql`
          SELECT po.id, po.external_po_number, po.status, po.order_date, s.name as supplier_name,
            COALESCE(SUM(poi.total_price), 0)::numeric as total_amount, COUNT(poi.id) as item_count
          FROM purchase_orders po LEFT JOIN suppliers s ON s.id = po.supplier_id
            LEFT JOIN purchase_order_items poi ON poi.purchase_order_id = po.id
          WHERE po.project_id::text = ${projectId}::text AND po.status NOT IN ('draft', 'cancelled')
            AND po.order_date <= ${to}::date
          GROUP BY po.id, po.external_po_number, po.status, po.order_date, s.name
          ORDER BY po.order_date DESC NULLS LAST`;
      } else {
        rows = await sql`
          SELECT po.id, po.external_po_number, po.status, po.order_date, s.name as supplier_name,
            COALESCE(SUM(poi.total_price), 0)::numeric as total_amount, COUNT(poi.id) as item_count
          FROM purchase_orders po LEFT JOIN suppliers s ON s.id = po.supplier_id
            LEFT JOIN purchase_order_items poi ON poi.purchase_order_id = po.id
          WHERE po.project_id::text = ${projectId}::text AND po.status NOT IN ('draft', 'cancelled')
          GROUP BY po.id, po.external_po_number, po.status, po.order_date, s.name
          ORDER BY po.order_date DESC NULLS LAST`;
      }

      const transactions = rows.map((r) => ({
        id: r.id,
        poNumber: r.external_po_number || '—',
        status: r.status,
        orderDate: r.order_date,
        supplierName: r.supplier_name || 'Unknown',
        totalAmount: Number(r.total_amount),
        itemCount: Number(r.item_count),
        confirmed: ['received', 'partially_received', 'closed'].includes(r.status),
      }));

      return apiResponse.success(res, { transactions });
    } catch (err) {
      log.error('Failed to load project PO transactions', { err, projectId }, 'boq-spend-summary');
      return apiResponse.serverError(res, err instanceof Error ? err.message : 'Unknown error');
    }
  }

  try {
    const projects = await sql`
      SELECT
        p.id as project_id,
        p.project_name,
        b.id as boq_id,
        b.version as boq_version,
        (SELECT COUNT(*) FROM boq_items WHERE boq_id = b.id) as boq_line_count,
        (SELECT COALESCE(SUM(unit_price * quantity), 0) FROM boq_items WHERE boq_id = b.id)::numeric as boq_value,
        (
          SELECT COALESCE(SUM(poi.total_price), 0)
          FROM purchase_order_items poi
          JOIN purchase_orders po ON po.id = poi.purchase_order_id
          WHERE po.project_id::text = p.id::text
            AND po.status NOT IN ('draft', 'cancelled')
        )::numeric as total_ordered,
        (
          SELECT COALESCE(SUM(poi.total_price), 0)
          FROM purchase_order_items poi
          JOIN purchase_orders po ON po.id = poi.purchase_order_id
          WHERE po.project_id::text = p.id::text
            AND po.status IN ('received', 'partially_received', 'closed')
        )::numeric as confirmed_spend,
        (
          SELECT COUNT(DISTINCT po.id)
          FROM purchase_orders po
          WHERE po.project_id::text = p.id::text
        ) as po_count
      FROM projects p
      JOIN boqs b ON b.project_id::text = p.id::text AND b.status = 'active'
      ORDER BY boq_value DESC
    `;

    const summary = projects.map((r) => {
      const boqValue = Number(r.boq_value);
      const totalOrdered = Number(r.total_ordered);
      const confirmedSpend = Number(r.confirmed_spend);

      return {
        projectId: r.project_id,
        projectName: r.project_name,
        boqId: r.boq_id,
        boqVersion: r.boq_version,
        boqLineCount: Number(r.boq_line_count),
        boqValue,
        totalOrdered,
        confirmedSpend,
        remainingBudget: Math.max(0, boqValue - totalOrdered),
        orderedPercent: boqValue > 0 ? Math.round((totalOrdered / boqValue) * 100) : 0,
        confirmedPercent: boqValue > 0 ? Math.round((confirmedSpend / boqValue) * 100) : 0,
        poCount: Number(r.po_count),
      };
    });

    const totals = {
      boqValue: summary.reduce((s, r) => s + r.boqValue, 0),
      totalOrdered: summary.reduce((s, r) => s + r.totalOrdered, 0),
      confirmedSpend: summary.reduce((s, r) => s + r.confirmedSpend, 0),
      remainingBudget: summary.reduce((s, r) => s + r.remainingBudget, 0),
    };

    return apiResponse.success(res, { projects: summary, totals });
  } catch (err) {
    log.error('Failed to load BOQ spend summary', { err }, 'boq-spend-summary');
    return apiResponse.serverError(res, err instanceof Error ? err.message : 'Unknown error');
  }
}

const withBundleAnalyzer = require('@next/bundle-analyzer')({
  enabled: process.env.ANALYZE === 'true',
})

// Inject build-time version info (git SHA, timestamp)
const { execSync } = require('child_process');
const getGitSha = () => {
  try { return execSync('git rev-parse HEAD', { stdio: ['pipe', 'pipe', 'pipe'] }).toString().trim(); }
  catch { return process.env.GIT_SHA || 'unknown'; }
};
const BUILD_GIT_SHA = getGitSha();
const BUILD_TIMESTAMP = new Date().toISOString();

/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: false,

  // Build-time version info — available in server-side code via process.env
  env: {
    GIT_SHA: BUILD_GIT_SHA,
    GIT_SHA_SHORT: BUILD_GIT_SHA.slice(0, 8),
    BUILD_TIMESTAMP,
  },

  // TypeScript and ESLint
  typescript: {
    ignoreBuildErrors: true,
  },
  eslint: {
    ignoreDuringBuilds: true,
  },

  // Performance optimizations
  compiler: {
    // Remove console logs in production
    removeConsole: process.env.NODE_ENV === 'production' ? {
      exclude: ['error', 'warn'],
    } : false,
  },

  // Image optimization
  images: {
    formats: ['image/webp', 'image/avif'],
    deviceSizes: [640, 750, 828, 1080, 1200, 1920, 2048, 3840],
    imageSizes: [16, 32, 48, 64, 96, 128, 256, 384],
    minimumCacheTTL: 60,
    dangerouslyAllowSVG: true,
    contentDispositionType: 'attachment',
    contentSecurityPolicy: "default-src 'self'; script-src 'none'; sandbox;",
    remotePatterns: [
      {
        protocol: 'https',
        hostname: 'placehold.co',
        pathname: '/**',
      },
      {
        protocol: 'https',
        hostname: 'firebasestorage.googleapis.com',
        pathname: '/**',
      },
    ],
  },

  // Disable static generation to prevent SSR issues
  experimental: {
    // Enable optimized package imports for tree-shaking
    optimizePackageImports: [
      '@tanstack/react-query',
      'react-icons',
      'lucide-react',
      'date-fns',
      'zod',
      'react-hot-toast',
      '@heroicons/react',
    ],
  },

  // Security and performance headers
  generateEtags: false,
  poweredByHeader: false,
  compress: true, // Enable gzip compression

  // Cache headers to prevent stale JavaScript errors during active development
  async headers() {
    return [
      {
        // HTML pages - always revalidate (prevents stale JS references)
        source: '/:path*',
        has: [
          {
            type: 'header',
            key: 'accept',
            value: '.*text/html.*',
          },
        ],
        headers: [
          {
            key: 'Cache-Control',
            value: 'no-cache, must-revalidate',
          },
        ],
      },
      {
        // Static assets with hashes - cache for 1 year (safe because filename changes)
        source: '/_next/static/:path*',
        headers: [
          {
            key: 'Cache-Control',
            value: 'public, max-age=31536000, immutable',
          },
        ],
      },
      {
        // API routes - never cache
        source: '/api/:path*',
        headers: [
          {
            key: 'Cache-Control',
            value: 'no-store, no-cache, must-revalidate',
          },
        ],
      },
    ];
  },

  // Redirects for backwards compatibility
  async redirects() {
    return [
      // dr-photo-unified → activate redirects
      {
        source: '/dr-photo-unified',
        destination: '/activate',
        permanent: true,
      },
      {
        source: '/dr-photo-unified/:path*',
        destination: '/activate/:path*',
        permanent: true,
      },
      {
        source: '/api/dr-photo-unified/:path*',
        destination: '/api/activate/:path*',
        permanent: true,
      },

      // Procurement menu restructure redirects (old list pages → new tab pages)
      // Sourcing
      {
        source: '/suppliers',
        destination: '/procurement/sourcing?tab=suppliers',
        permanent: true,
      },
      {
        source: '/procurement/boq',
        destination: '/procurement/sourcing?tab=boq',
        permanent: true,
      },
      {
        source: '/procurement/rfq',
        destination: '/procurement/sourcing?tab=rfq',
        permanent: true,
      },
      // Purchasing
      {
        source: '/procurement/quotes',
        destination: '/procurement/purchasing?tab=quotes',
        permanent: true,
      },
      {
        source: '/procurement/requisitions',
        destination: '/procurement/purchasing?tab=requisitions',
        permanent: true,
      },
      {
        source: '/procurement/purchase-orders',
        destination: '/procurement/purchasing?tab=purchase-orders',
        permanent: true,
      },
      {
        source: '/procurement/grn',
        destination: '/procurement/purchasing?tab=grn',
        permanent: true,
      },
      // Inventory
      {
        source: '/procurement/stock',
        destination: '/procurement/inventory?tab=stock',
        permanent: true,
      },
      {
        source: '/procurement/stock-items',
        destination: '/procurement/inventory?tab=items',
        permanent: true,
      },
      {
        source: '/procurement/stock-categories',
        destination: '/procurement/inventory?tab=categories',
        permanent: true,
      },
      {
        source: '/procurement/bundles',
        destination: '/procurement/inventory?tab=bundles',
        permanent: true,
      },
      {
        source: '/procurement/stock-takes',
        destination: '/procurement/inventory?tab=takes',
        permanent: true,
      },
      // field-stock has its own standalone page with 8 sub-tabs (PRD-027)
      // Financial
      {
        source: '/procurement/budget',
        destination: '/procurement/financial?tab=budget',
        permanent: true,
      },
      {
        source: '/procurement/cost-centers',
        destination: '/procurement/financial?tab=cost-centers',
        permanent: true,
      },
    ];
  },

  // DISABLED: Legacy neon/api/server.ts proxy - zero-auth CRUD server
  // The Neon API server has no authentication and should not be proxied.
  // SOW imports now use proper Next.js API routes with withAuth.
  // If you need this, add auth to neon/api/server.ts first.
  // async rewrites() {
  //   return [
  //     { source: '/poles', destination: 'http://localhost:3001/' },
  //     { source: '/poles/:path*', destination: 'http://localhost:3001/:path*' },
  //   ];
  // },

  // Fix file watching issues
  webpack: (config, { dev, isServer }) => {
    // Try to fix Watchpack issues with minimal configuration
    if (dev && !isServer) {
      config.watchOptions = {
        ignored: ['**/node_modules/**'],
        aggregateTimeout: 300,
        poll: 1000,
      };
    }

    // Let Next.js handle chunk splitting (its defaults are well-optimized)

    // Ensure proper handling of undefined paths
    if (config.resolve && config.resolve.alias) {
      // Remove any undefined aliases that might cause issues
      Object.keys(config.resolve.alias).forEach(key => {
        if (config.resolve.alias[key] === undefined) {
          delete config.resolve.alias[key];
        }
      });
    }

    return config;
  },

  // Disable static optimization to prevent router mounting issues
  trailingSlash: false,
};

module.exports = withBundleAnalyzer(nextConfig);

