 303→// ============================================================================
 304→// VALIDATION HELPERS
 305→// ============================================================================
 306→
 307→/**
 308→ * Validate ONT serial format
 309→ * - Must start with ALCL or ALCB
 310→ * - Must be 11-12 characters
 311→ * - Must NOT be an SSID (ALHN-*)
 312→ */
 313→function isValidOntSerial(serial: string | null): boolean {
 314→  if (!serial) return false;
 315→  const s = serial.trim().toUpperCase();
 316→
 317→  // Hallucination guard — reject prompt examples
 318→  if (isPromptExampleSerial(s)) return false;
 319→
 320→  // Reject SSID patterns (common VLM mistake)
 321→  if (s.startsWith('ALHN') || s.startsWith('ALH-') || s.includes('-')) {
 322→    logger.debug(`Rejected SSID-like value: ${serial}`);
 323→    return false;
 324→  }
 325→
 326→  // Must start with ALCLB4 (all Nokia ONTs in this network)
 327→  if (!s.startsWith('ALCLB4')) {
 328→    logger.debug(`Rejected non-ALCLB4 serial: ${serial}`);
 329→    return false;
 330→  }
 331→
 332→  // Must be exactly 12 chars (all OES-confirmed serials are 12 chars)
 333→  if (s.length !== 12) {
 334→    logger.debug(`Rejected serial with wrong length (${s.length}): ${serial}`);
 335→    return false;
 336→  }
 337→
 338→  // Suffix after ALCLB4 must be hex only (0-9, A-F)
 339→  const suffix = s.substring(6);
 340→  if (!/^[0-9A-F]{6}$/.test(suffix)) {
 341→    logger.debug(`Rejected serial with non-hex suffix: ${serial}`);
 342→    return false;
 343→  }
 344→
 345→  return true;
 346→}
 347→
 348→/**
 349→ * Clean and normalize extracted serial
 350→ * Fixes common VLM extraction errors based on OES ground truth analysis
 351→ */
 352→function normalizeSerial(serial: string | null): string | null {
 353→  if (!serial) return null;
 354→  let s = serial.trim().toUpperCase();
 355→
 356→  // Remove any spaces, dashes, or commas
 357→  s = s.replace(/[\s\-,]/g, '');
 358→
 359→  // Fix non-hex chars in the suffix (after ALCLB4) — common VLM OCR errors
 360→  if (s.startsWith('ALCLB4') && s.length >= 7) {
 361→    const prefix = s.substring(0, 6);
 362→    let suffix = s.substring(6);
 363→    // Replace common OCR misreads with closest hex char
 364→    suffix = suffix.replace(/[GI]/g, '6'); // G/I → 6
 365→    suffix = suffix.replace(/[O]/g, '0');  // O → 0
 366→    suffix = suffix.replace(/[S]/g, '5');  // S → 5
 367→    suffix = suffix.replace(/[Z]/g, '2');  // Z → 2
 368→    // Remove any remaining non-hex chars
 369→    suffix = suffix.replace(/[^0-9A-F]/g, '');
 370→    s = prefix + suffix;
 371→  }
 372→
 373→  // Auto-fix: If VLM returns 11 chars starting with ALCLB4, try inserting the most
 374→  // likely 7th char ('8' at 64%, '7' at 26%, '6' at 10%) if it makes a valid suffix.
 375→  // Only insert if the 7th char is NOT already 8/7/6 (meaning a different char was dropped).
 376→  if (s.length === 11 && s.startsWith('ALCLB4')) {
 377→    const c7 = s[6]; // Current 7th char (0-indexed position 6)
 378→    // If the 7th char looks like it belongs at position 8+ (hex suffix char),
 379→    // the VLM likely dropped the actual 7th char. Try inserting '8' (most common).
 380→    if (c7 !== '8' && c7 !== '7' && c7 !== '6') {
 381→      const candidate = s.substring(0, 6) + '8' + s.substring(6);
 382→      logger.debug(`Auto-inserted '8' at pos 7: ${serial} → ${candidate}`);
 383→      s = candidate;
 384→    }
 385→    // Otherwise leave as-is — the VLM may have dropped a later char
 386→  }
 387→
 388→  return s;
 389→}
