 394→
 395→/**
 396→ * Call VLM API with image and prompt
 397→ */
 398→async function callVlmExtraction<T>(
 399→  base64Image: string,
 400→  prompt: string,
 401→  context: string
 402→): Promise<{ success: boolean; data: T | null; error?: string }> {
 403→  const requestBody = {
 404→    model: VLM_MODEL,
 405→    messages: [
 406→      {
 407→        role: 'user',
 408→        content: [
 409→          { type: 'text', text: prompt },
 410→          {
 411→            type: 'image_url',
 412→            image_url: { url: `data:image/jpeg;base64,${base64Image}` },
 413→          },
 414→        ],
 415→      },
 416→    ],
 417→    max_tokens: 1000,
 418→    temperature: VLM_TEMPERATURE,
 419→  };
 420→
 421→  const controller = new AbortController();
 422→  const timeoutId = setTimeout(() => controller.abort(), VLM_TIMEOUT_MS);
 423→
 424→  try {
 425→    const response = await fetch(VLM_API_ENDPOINT, {
 426→      method: 'POST',
 427→      headers: { 'Content-Type': 'application/json' },
 428→      body: JSON.stringify(requestBody),
 429→      signal: controller.signal,
 430→    });
 431→
 432→    clearTimeout(timeoutId);
 433→
 434→    if (!response.ok) {
 435→      const errorText = await response.text();
 436→      throw new Error(`VLM API returned ${response.status}: ${errorText}`);
 437→    }
 438→
 439→    const data = await response.json();
 440→    const content = data.choices?.[0]?.message?.content;
 441→
 442→    if (!content) {
 443→      throw new Error('No content in VLM response');
 444→    }
 445→
 446→    // Extract JSON from response (handle markdown code blocks)
 447→    const jsonMatch =
 448→      content.match(/```json\n([\s\S]*?)\n```/) ||
 449→      content.match(/```\n([\s\S]*?)\n```/) ||
 450→      [null, content];
 451→
 452→    const parsed = JSON.parse(jsonMatch[1] || content);
 453→
 454→    return { success: true, data: parsed };
 455→  } catch (error: unknown) {
 456→    clearTimeout(timeoutId);
 457→
 458→    const message = error instanceof Error ? error.message : String(error);
 459→    log.error(`${context}: ${message}`, undefined, 'VlmExtraction');
 460→
 461→    return { success: false, data: null, error: message };
 462→  }
 463→}
