 469→/**
 470→ * Preprocess image before VLM extraction
 471→ * - Detects blur and optionally deblurs
 472→ * - Optimizes image size for VLM
 473→ *
 474→ * @param base64 - Base64 encoded image
 475→ * @param context - Context for logging
 476→ * @returns Preprocessed base64 image
 477→ */
 478→async function preprocessForVlm(
 479→  base64: string,
 480→  context: string
 481→): Promise<{ base64: string; blurResult?: BlurDetectionResult }> {
 482→  // If preprocessing is disabled, just optimize size
 483→  if (!ENABLE_BLUR_DETECTION && !ENABLE_IMAGE_PREPROCESSING) {
 484→    const optimized = await optimizeForVlm(base64);
 485→    return { base64: optimized };
 486→  }
 487→
 488→  // Detect blur
 489→  const blurResult = await detectBlur(base64);
 490→
 491→  if (blurResult.isBlurry) {
 492→    logger.warn(`${context}: Image is ${blurResult.assessment} (score: ${blurResult.score.toFixed(1)})`, {
 493→      score: blurResult.score,
 494→      threshold: blurResult.threshold,
 495→    });
 496→
 497→    // If full preprocessing is enabled, try to deblur
 498→    if (ENABLE_IMAGE_PREPROCESSING) {
 499→      const preprocessResult = await preprocessImage(base64, { skipDeblur: false });
 500→
 501→      if (preprocessResult.wasPreprocessed && preprocessResult.deblur?.newScore) {
 502→        logger.info(`${context}: Deblurred image (${blurResult.score.toFixed(1)} → ${preprocessResult.deblur.newScore.toFixed(1)})`);
 503→        return { base64: preprocessResult.imageBase64, blurResult };
 504→      }
 505→    }
 506→  } else {
 507→    logger.debug(`${context}: Image is ${blurResult.assessment} (score: ${blurResult.score.toFixed(1)})`);
 508→  }
 509→
 510→  // Optimize for VLM (resize if needed)
 511→  const optimized = await optimizeForVlm(base64);
 512→  return { base64: optimized, blurResult };
 513→}
