 638→      error: result.error || 'Extraction failed',
 639→      extractionMethod: 'vlm',
 640→    };
 641→  }
 642→
 643→  const { found, serial, rawText, confidence } = result.data;
 644→
 645→  // Normalize and validate the extracted serial
 646→  const normalizedSerial = normalizeSerial(serial);
