1202→ * @param drNumber - DR number being processed
1203→ * @param photos - Map of step number to photo URL(s) - arrays preferred for better extraction
1204→ * @param options - Optional configuration including expectedOntSerial from OneMap
1205→ */
1206→export async function runFullExtraction(
1207→  drNumber: string,
1208→  photos: {
1209→    step6Url?: string;
1210→    step6Urls?: string[];
1211→    step7Url?: string;
1212→    step7Urls?: string[];
1213→    step9Url?: string;
1214→    step9Urls?: string[];
1215→  },
1216→  options?: {
1217→    /** If OneMap has the ONT serial, provide it here for confirmation mode */
1218→    expectedOntSerial?: string | null;
1219→  }
1220→): Promise<FullExtractionResult> {
1221→  const startTime = Date.now();
1222→  const expectedSerial = options?.expectedOntSerial;
1223→  const useConfirmationMode = !!expectedSerial && isValidOntSerial(expectedSerial);
1224→
1225→  logger.info(`Running ${useConfirmationMode ? 'CONFIRMATION' : 'EXTRACTION'} mode for ${drNumber}${useConfirmationMode ? ` (expecting ${expectedSerial})` : ''}`);
1226→
1227→  let powerMeter: PowerMeterExtraction | null = null;
1228→  let ontSerialStep6: SerialExtraction | null = null;
1229→  let step9: Step9Extraction | null = null;
1230→  let serialConfirmation: SerialConfirmation | null = null;
1231→
1232→  // Extract power meter from Step 7 - try multiple photos if provided
1233→  if (photos.step7Urls && photos.step7Urls.length > 0) {
1234→    const { result } = await extractPowerMeterWithMultiplePhotos(photos.step7Urls);
1235→    powerMeter = result;
1236→  } else if (photos.step7Url) {
1237→    powerMeter = await extractPowerMeterReading(photos.step7Url);
1238→  }
1239→  if (powerMeter) {
1240→    logger.debug(`Power meter result: ${powerMeter.success ? powerMeter.value + ' dBm' : 'failed'}`);
1241→  }
1242→
1243→  // SMART MODE: Use confirmation when OneMap has serial, otherwise extract
1244→  if (useConfirmationMode && expectedSerial) {
1245→    // ============================================
1246→    // CONFIRMATION MODE: Verify OneMap serial
1247→    // ============================================
1248→    logger.info(`Using CONFIRMATION mode for ${expectedSerial}`);
1249→
1250→    // Combine Step 6 and Step 9 photos for confirmation
1251→    const allSerialPhotos = [
1252→      ...(photos.step6Urls || []),
1253→      ...(photos.step6Url ? [photos.step6Url] : []),
1254→      ...(photos.step9Urls || []),
