1361→/**
1362→ * Check if DR numbers match (handles prefix variations)
1363→ */
1364→export function drNumbersMatch(extracted: string | null, expected: string): boolean {
1365→  if (!extracted) return false;
1366→
1367→  // Normalize both: remove "DR" prefix, spaces, and compare
1368→  const normalizedr = (s: string) =>
1369→    s
1370→      .replace(/^DR/i, '')
1371→      .replace(/\s+/g, '')
1372→      .toUpperCase();
1373→
1374→  return normalizedr(extracted) === normalizedr(expected);
1375→}
