}

CRITICAL: If you cannot read a clear 12-char serial starting with ALCLB4, return found: false.
Returning null is ALWAYS better than guessing. Do NOT invent or fabricate serial numbers.`;

/**
 * Build a confirmation prompt for verifying a known serial is visible
 * This is used when OneMap already has the serial - we just confirm it's in the photo
 */
function buildSerialConfirmationPrompt(expectedSerial: string): string {
  return `You are verifying that a specific ONT serial number is visible in this photo.

EXPECTED SERIAL: ${expectedSerial}

Your task: Check if this exact serial (or very close match) is visible anywhere in the photo.

The serial should:
- Start with "ALCLB4" and be exactly 12 characters
- Be on a white sticker/label
- May be near a barcode or under "S/N:" text

Respond in this exact JSON format:
{
  "confirmed": true/false,
  "confidence": <0.0 to 1.0>,
  "visibleText": "<what you actually see on the label, or null>",
  "alternativeSerial": "<if you see a DIFFERENT serial starting with ALCL/ALCB, put it here, otherwise null>",
  "details": "<brief explanation of what you found>"
}

IMPORTANT:
- "confirmed": true means you can see "${expectedSerial}" or a very close match (1-2 character difference is OK)
- If the serial is partially obscured but you can make out most of it matching, that's confirmed
- If you see a completely different serial, set confirmed=false and put it in alternativeSerial
- If you can't see any serial clearly, set confirmed=false with null alternativeSerial`;
}

// ============================================================================
// VALIDATION HELPERS
// ============================================================================

/**
 * Validate ONT serial format
 * - Must start with ALCL or ALCB
 * - Must be 11-12 characters
 * - Must NOT be an SSID (ALHN-*)
 */
function isValidOntSerial(serial: string | null): boolean {
  if (!serial) return false;
  const s = serial.trim().toUpperCase();

  // Hallucination guard — reject prompt examples
  if (isPromptExampleSerial(s)) return false;

  // Reject SSID patterns (common VLM mistake)
  if (s.startsWith('ALHN') || s.startsWith('ALH-') || s.includes('-')) {
    logger.debug(`Rejected SSID-like value: ${serial}`);
    return false;
  }

  // Must start with ALCLB4 (all Nokia ONTs in this network)
  if (!s.startsWith('ALCLB4')) {
    logger.debug(`Rejected non-ALCLB4 serial: ${serial}`);
    return false;
  }

  // Must be exactly 12 chars (all OES-confirmed serials are 12 chars)
  if (s.length !== 12) {
    logger.debug(`Rejected serial with wrong length (${s.length}): ${serial}`);
    return false;
  }

  // Suffix after ALCLB4 must be hex only (0-9, A-F)
  const suffix = s.substring(6);
  if (!/^[0-9A-F]{6}$/.test(suffix)) {
    logger.debug(`Rejected serial with non-hex suffix: ${serial}`);
    return false;
  }

  return true;
}

/**
 * Clean and normalize extracted serial
 * Fixes common VLM extraction errors based on OES ground truth analysis
 */
function normalizeSerial(serial: string | null): string | null {
  if (!serial) return null;
  let s = serial.trim().toUpperCase();

  // Remove any spaces, dashes, or commas
  s = s.replace(/[\s\-,]/g, '');

  // Fix non-hex chars in the suffix (after ALCLB4) — common VLM OCR errors
  if (s.startsWith('ALCLB4') && s.length >= 7) {
    const prefix = s.substring(0, 6);
    let suffix = s.substring(6);
    // Replace common OCR misreads with closest hex char
    suffix = suffix.replace(/[GI]/g, '6'); // G/I → 6
    suffix = suffix.replace(/[O]/g, '0');  // O → 0
    suffix = suffix.replace(/[S]/g, '5');  // S → 5
    suffix = suffix.replace(/[Z]/g, '2');  // Z → 2
    // Remove any remaining non-hex chars
    suffix = suffix.replace(/[^0-9A-F]/g, '');
    s = prefix + suffix;
  }

  // Auto-fix: If VLM returns 11 chars starting with ALCLB4, try inserting the most
  // likely 7th char ('8' at 64%, '7' at 26%, '6' at 10%) if it makes a valid suffix.
  // Only insert if the 7th char is NOT already 8/7/6 (meaning a different char was dropped).
  if (s.length === 11 && s.startsWith('ALCLB4')) {
    const c7 = s[6]; // Current 7th char (0-indexed position 6)
    // If the 7th char looks like it belongs at position 8+ (hex suffix char),
    // the VLM likely dropped the actual 7th char. Try inserting '8' (most common).
    if (c7 !== '8' && c7 !== '7' && c7 !== '6') {
      const candidate = s.substring(0, 6) + '8' + s.substring(6);
      logger.debug(`Auto-inserted '8' at pos 7: ${serial} → ${candidate}`);
      s = candidate;
    }
    // Otherwise leave as-is — the VLM may have dropped a later char
  }

  return s;
}

