    return c;
  });

  const overall: OverallStatus =
    qfieldApp.status === 'up' && minioHealth.status === 'up'
      ? 'healthy'
      : qfieldApp.status === 'down' || minioHealth.status === 'down'
        ? 'critical'
        : 'degraded';

  return {
    overall,
    containers: updatedContainers,
    syncWebhook,
    totalContainers: QFIELD_CONTAINERS.length,
    runningContainers,
  };
}

