    // QField
    checkQFieldStatus(),
    // Databases
    checkDatabaseHealth(DATABASE_URL, 'Neon Production', 'production'),
    // Recovery actions
    includeRecoveryLog ? getRecentRecoveryActions(recoveryLogLimit) : Promise.resolve([]),
  ]);

