/**
 * API Client for Vercel Serverless Functions
 * Handles all database operations through API routes
 */

import { log } from '@/lib/logger';

// Get the base URL for API
const getBaseUrl = () => {
  // In development, use local dev server
  if (process.env.NODE_ENV === 'development') {
    return 'http://localhost:5173/api';
  }

  // In production, use relative path (works on same domain)
  return '/api';
};

const BASE_URL = getBaseUrl();

// Helper function to make API calls
async function apiCall<T = any>(
  endpoint: string,
  options: RequestInit = {}
): Promise<T> {
  try {
    const url = `${BASE_URL}/${endpoint}`;

    const response = await fetch(url, {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });

    if (!response.ok) {
      const error = await response.json().catch(() => ({ message: 'Request failed' }));
      throw new Error(error.message || `HTTP ${response.status}: ${response.statusText}`);
    }

    const data = await response.json();

    if (data.success === false) {
      throw new Error(data.error || 'Operation failed');
    }

    return data.data || data;
  } catch (error) {
    log.error(`API call to ${endpoint} failed`, error instanceof Error ? { message: error.message } : { error }, 'FirebaseApi');
    throw error;
  }
}

// Client API
export const clientsApi = {
  getAll: () => apiCall('clients'),
  getById: (id: string) => apiCall(`clients?id=${id}`),
  create: (data: any) => apiCall('clients', {
    method: 'POST',
    body: JSON.stringify(data),
  }),
  update: (id: string, data: any) => apiCall(`clients?id=${id}`, {
    method: 'PUT',
    body: JSON.stringify(data),
  }),
  delete: (id: string) => apiCall(`clients?id=${id}`, {
    method: 'DELETE',
  }),
};

// Projects API
export const projectsApi = {
  getAll: () => apiCall('projects'),
  getById: (id: string) => apiCall(`projects?id=${id}`),
  create: (data: any) => apiCall('projects', {
    method: 'POST',
    body: JSON.stringify(data),
  }),
};

// Staff API
export const staffApi = {
  getAll: () => apiCall('staff'),
  getById: (id: string) => apiCall(`staff?id=${id}`),
  create: (data: any) => apiCall('staff', {
    method: 'POST',
    body: JSON.stringify(data),
  }),
};

// Generic query API
export const queryApi = {
  query: (table: string, filters?: Record<string, any>, limit?: number) => 
    apiCall('query', {
      method: 'POST',
      body: JSON.stringify({ table, filters, limit }),
    }),
};

// Health check
export const healthCheck = () => apiCall('health');

// Export a unified API object
export const firebaseApi = {
  clients: clientsApi,
  projects: projectsApi,
  staff: staffApi,
  query: queryApi,
  health: healthCheck,
};

}

interface RawPoScopeRow {
  project_id: string;
  po_total_scope: string;
}

async function handler(
  req: NextApiRequest,
  res: NextApiResponse<MaturityTrackingResponse | { error: string }>
) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET','POST']);
  }

  try {
    const { project, view = 'hierarchy' } = req.query;

    const projectFilter = project ? (Array.isArray(project) ? project[0] : project) : null;
    const isUuid = projectFilter
      ? /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(projectFilter)
      : false;
    const viewMode = (Array.isArray(view) ? view[0] : view) as 'hierarchy' | 'flat';

    log.info('MaturityTracking', 'Fetching maturity data', {
      project: projectFilter,
      isUuid,
      view: viewMode,
    });

    const client = await pool.connect();

    try {
      // Query 0: Get PO contracted drops per project (business target)
      // Falls back to SOW drop count if no PO exists
      const poScopeQuery = `
        SELECT
          cpo.project_id::text as project_id,
          SUM(cpo.contracted_drops)::text as po_total_scope
        FROM client_purchase_orders cpo
        JOIN projects p ON p.id = cpo.project_id
        WHERE p.status = 'active'
          AND (
            $1::text IS NULL
            OR ($2::boolean = true AND cpo.project_id = $1::uuid)
            OR ($2::boolean = false AND p.project_name = $1::text)
          )
        GROUP BY cpo.project_id
      `;

    recentDRs: [],
  } as ActivatorPerformance);
}

const matchParams = [dateFromStr, dateToStr, identifier];
const matchClause = `qpr.user_name = $3`;

// Get performance summary
const summaryResult = await pool.query(
  `
  WITH tech_submissions AS (
    SELECT
      qpr.drop_number,
      qpr.project,
      upr.submission_count,
      upr.ont_serial_scanned,
      upr.ups_serial_scanned,
      COALESCE(upr.submitted_date, upr.created_at::DATE) as submitted_date
    FROM qa_photo_reviews qpr
    INNER JOIN dr_photo_unified_reviews upr ON qpr.drop_number = upr.drop_number
    WHERE ${matchClause}
      AND COALESCE(upr.submitted_date, upr.created_at::DATE) >= $1::DATE
      AND COALESCE(upr.submitted_date, upr.created_at::DATE) <= $2::DATE
  )
  SELECT
    COUNT(DISTINCT drop_number) as total_submissions,
    COUNT(DISTINCT drop_number) FILTER (WHERE submission_count = 1) as first_pass_success,
    COUNT(DISTINCT drop_number) FILTER (WHERE submission_count > 1) as resubmissions,
    COUNT(DISTINCT drop_number) FILTER (WHERE ont_serial_scanned IS NOT NULL AND ont_serial_scanned != '') as ont_scanned,
    COUNT(DISTINCT drop_number) FILTER (WHERE ups_serial_scanned IS NOT NULL AND ups_serial_scanned != '') as ups_scanned,
    ARRAY_AGG(DISTINCT project) FILTER (WHERE project IS NOT NULL) as projects,
    COUNT(DISTINCT submitted_date) as active_days
  FROM tech_submissions
  `,
  matchParams
);

const summary = summaryResult.rows[0] || {};
const totalSubmissions = parseInt(summary.total_submissions) || 0;
const firstPassSuccess = parseInt(summary.first_pass_success) || 0;
const resubmissions = parseInt(summary.resubmissions) || 0;
const ontScanned = parseInt(summary.ont_scanned) || 0;
const upsScanned = parseInt(summary.ups_scanned) || 0;

// Get daily trend
const trendResult = await pool.query(
  `
  WITH tech_submissions AS (
    SELECT
      COALESCE(upr.submitted_date, upr.created_at::DATE) as date_val,
      upr.submission_count
    FROM qa_photo_reviews qpr
    INNER JOIN dr_photo_unified_reviews upr ON qpr.drop_number = upr.drop_number
    WHERE ${matchClause}
      AND COALESCE(upr.submitted_date, upr.created_at::DATE) >= $1::DATE
      AND COALESCE(upr.submitted_date, upr.created_at::DATE) <= $2::DATE
  )
  SELECT
    date_val::TEXT as date,
    COUNT(*) as submissions,
    COUNT(*) FILTER (WHERE submission_count = 1) as first_pass,
    COUNT(*) FILTER (WHERE submission_count > 1) as resubmissions
  FROM tech_submissions
  GROUP BY date_val
  ORDER BY date_val
  `,
  matchParams
);

// Get project breakdown
const projectResult = await pool.query(
  `
  WITH tech_submissions AS (
    SELECT
      qpr.project,
      upr.submission_count,
      upr.ont_serial_scanned
    FROM qa_photo_reviews qpr
    INNER JOIN dr_photo_unified_reviews upr ON qpr.drop_number = upr.drop_number
    WHERE ${matchClause}
      AND COALESCE(upr.submitted_date, upr.created_at::DATE) >= $1::DATE
      AND COALESCE(upr.submitted_date, upr.created_at::DATE) <= $2::DATE
      AND qpr.project IS NOT NULL
  )
  SELECT
    project,
    COUNT(*) as submissions,
    ROUND(COUNT(*) FILTER (WHERE submission_count = 1)::NUMERIC / NULLIF(COUNT(*), 0) * 100) as first_pass_rate,
    ROUND(COUNT(*) FILTER (WHERE ont_serial_scanned IS NOT NULL AND ont_serial_scanned != '')::NUMERIC / NULLIF(COUNT(*), 0) * 100) as serial_compliance_rate
  FROM tech_submissions
  GROUP BY project
  ORDER BY submissions DESC
  `,
  matchParams
);

// Get recent DRs for this activator
const recentDRsResult = await pool.query(
  `
  SELECT DISTINCT ON (qpr.drop_number)
    qpr.drop_number,
    qpr.project,
    COALESCE(upr.submitted_date, upr.created_at::DATE)::TEXT as date,
    upr.submission_count,
    upr.qa_decision
  FROM qa_photo_reviews qpr
  INNER JOIN dr_photo_unified_reviews upr ON qpr.drop_number = upr.drop_number
  WHERE ${matchClause}
    AND COALESCE(upr.submitted_date, upr.created_at::DATE) >= $1::DATE
    AND COALESCE(upr.submitted_date, upr.created_at::DATE) <= $2::DATE

