/**
 * Staff Types - Re-export all staff type definitions
 * This file maintains backward compatibility while organizing types into smaller modules
 *
 * NOTE: Firebase has been removed. Using local TimestampLike type instead.
 */

export * from './staff/index';

// Re-export Timestamp-like type for backward compatibility
// Firebase has been removed, using a compatible interface instead
export interface TimestampLike {
  seconds: number;
  nanoseconds: number;
  toDate(): Date;
}

/**
 * Create a Timestamp-like object from a Date
 */
export function createTimestamp(date: Date = new Date()): TimestampLike {
  return {
    seconds: Math.floor(date.getTime() / 1000),
    nanoseconds: (date.getTime() % 1000) * 1000000,
    toDate() {
      return new Date(this.seconds * 1000 + this.nanoseconds / 1000000);
    }
  };
}

/**
 * Staff Base Types - Core staff member definitions
 */

import { Timestamp } from 'firebase/firestore';
import {
  Department, Position, StaffLevel, StaffStatus, ContractType,
  Skill, Certification, Equipment, TrainingRecord,
  SAContractType, SAComplianceData, ExitType
} from './enums.types';

export interface StaffMember {
  id?: string;

  // Personal Information
  name: string;
  email: string;
  phone: string;
  alternativePhone?: string;
  whatsappId?: string; // WhatsApp LID for @mention tagging in QA feedback

  // Employment Details
  employeeId: string;
  position: Position | string; // Allow Position enum or custom string
  department: Department;
  level?: StaffLevel; // Optional for backward compatibility
  status: StaffStatus;
  isActive?: boolean;
  lastActiveDate?: Timestamp;

  // Manager/Reporting
  managerId?: string;
  managerName?: string;
  managerPosition?: string;
  managerEmployeeId?: string;
  reportsTo?: string;

  // Skills and Certifications
  skills: Skill[];
  certifications: Certification[];
  experienceYears: number;
  specializations: string[];

  // Contact Information
  address: string;
  city: string;
  province: string;
  postalCode: string;
  emergencyContactName?: string;
  emergencyContactPhone?: string;
  emergencyContactRelationship?: string;

  // Next of Kin (separate from emergency contact)
  nextOfKinName?: string;
  nextOfKinPhone?: string;
  nextOfKinRelationship?: string;
  nextOfKinAddress?: string;

  // Employment Terms
  startDate: Timestamp;
  endDate?: Timestamp;
  /** @deprecated Use saContractType instead */
  contractType: ContractType;
  /** SA Labour Law compliant contract type */
  saContractType?: SAContractType;
  salaryGrade?: string;
  hourlyRate?: number;
  taxNumber?: string;
  bankAccountNumber?: string;
  bankName?: string;
  bankBranchCode?: string;
  bankAccountType?: 'current' | 'savings' | 'transmission';
  bankAccountHolder?: string;
  /** Timestamp when bank details were verified via document upload */
  bankDetailsVerifiedAt?: Timestamp;
  salaryAmount?: number;
  benefitsPackage?: string;
  noticePeriodDays?: number;

  // SA Identity Documents
  saIdNumber?: string;
  passportNumber?: string;
  passportCountry?: string;
  passportExpiry?: Timestamp | string;
  nationality?: string;

  // Probation
  probationEndDate?: Timestamp;
  probationExtended?: boolean;
  probationExtensionReason?: string;

  // SA Labour Compliance
  /** South African labour law compliance data */
  saCompliance?: SAComplianceData;
  /** True if staff member is an employee (not independent contractor) */
  isEmployee?: boolean;
  /** Currently in probation period */
  inProbation?: boolean;
  /** All required compliance fields are completed */
  complianceComplete?: boolean;

  // Flat compliance fields (for API and forms)
  /** UIF registration status */
  uifStatus?: string;
  /** UIF registration number */
  uifNumber?: string;
  /** COIDA registration status */
  coidaStatus?: string;
  /** Tax status (PAYE, provisional, etc.) */
  taxStatus?: string;
  /** Probation status */
  probationStatus?: string;
  /** Notice period type */
  noticePeriod?: string;
  /** Weekly working hours */
  weeklyHours?: number;
  /** SA ID number (13 digits) */
  idNumber?: string;
  /** Work permit number (for foreign nationals) */
  workPermitNumber?: string;
  /** Work permit expiry date */
  workPermitExpiry?: Timestamp | string;

  // Exit/Termination Data (for former employees)
  /** Type of exit - voluntary, involuntary, retirement, etc. */
  exitType?: ExitType;
  /** Detailed reason for leaving */
  exitReason?: string;
  /** Whether the employee can be rehired */
  isRehireable?: boolean;
  /** Staff ID of person who processed the exit */
  exitProcessedBy?: string;
  /** When the exit was processed */
  exitProcessedDate?: Timestamp;

  // Availability and Scheduling
  workingHours: string;
  workLocation?: string;
  workSchedule?: string;
  availableWeekends: boolean;
  availableNights: boolean;
  timeZone: string;

  // Project Assignments (current active projects)
  activeProjectIds: string[];
  currentProjectCount: number;
  maxProjectCount: number;

  // Performance Metrics
  totalProjectsCompleted: number;
  averageProjectRating: number;
  onTimeCompletionRate: number;
  performanceRating?: number;

  // Equipment and Tools
  assignedEquipment: Equipment[];
  vehicleAssigned?: string;
  toolsAssigned: string[];

  // Training and Development
  trainingRecords: TrainingRecord[];
  nextTrainingDue?: Timestamp;
  safetyTrainingExpiry?: Timestamp;

  // Notes and Comments
  notes?: string;
  performanceNotes?: string;

  // Audit Fields
  createdAt: Timestamp;
  updatedAt: Timestamp;
  createdBy: string;
  lastModifiedBy: string;

  // Profile & Photo Verification
  profilePhotoUrl?: string;
  bio?: string;
  /** Photo extracted from ID document (SA ID or Passport) via OCR */
  idPhotoUrl?: string;
  /** AI face comparison score (0-100%) between ID photo and profile photo */
  photoMatchScore?: number;
  /** Timestamp of last photo comparison */
  photoVerifiedAt?: Timestamp;

  // CV/Resume
  cvUrl?: string;
  cvUploadedAt?: Timestamp;

  // Company Vehicle Flag
  /** Whether staff is assigned a company vehicle (triggers license requirement) */
  hasCompanyVehicle?: boolean;
}

/**
 * Staff Assignment Types - Project assignments and roles
 */

import { Timestamp } from 'firebase/firestore';

export interface ProjectAssignment {
  id?: string;
  staffId: string;
  staffName: string;
  projectId: string;
  projectName: string;
  role: ProjectRole;
  startDate: Timestamp;
  endDate?: Timestamp;
  allocation: number; // Percentage of time allocated (0-100)
  status: AssignmentStatus;
  notes?: string;
  createdAt: Timestamp;
  updatedAt: Timestamp;
}

export enum ProjectRole {
  PROJECT_MANAGER = 'project_manager',
  LEAD_ENGINEER = 'lead_engineer',
  SENIOR_TECHNICIAN = 'senior_technician',
  TECHNICIAN = 'technician',
  INSTALLER = 'installer',
  QUALITY_INSPECTOR = 'quality_inspector',
  SUPPORT = 'support',
  COORDINATOR = 'coordinator',
}

export enum AssignmentStatus {
  ASSIGNED = 'assigned',
  ACTIVE = 'active',
  COMPLETED = 'completed',
  CANCELLED = 'cancelled',
  ON_HOLD = 'on_hold',
}

/**
 * Staff Timesheet Types - Time tracking and work records
 */

import { Timestamp } from 'firebase/firestore';

export interface Timesheet {
  id?: string;
  staffId: string;
  staffName: string;
  projectId?: string;
  projectName?: string;
  date: Timestamp;
  hoursWorked: number;
  workType: WorkType;
  description: string;
  location?: string;
  approvedBy?: string;
  approvedDate?: Timestamp;
  status: TimesheetStatus;
  createdAt: Timestamp;
  updatedAt: Timestamp;
}

export enum WorkType {
  REGULAR = 'regular',
  OVERTIME = 'overtime',
  WEEKEND = 'weekend',
  NIGHT_SHIFT = 'night_shift',
  TRAINING = 'training',
  MEETING = 'meeting',
  TRAVEL = 'travel',
  ADMIN = 'admin',
}

export enum TimesheetStatus {
  DRAFT = 'draft',
  SUBMITTED = 'submitted',
  APPROVED = 'approved',
  REJECTED = 'rejected',
  PAID = 'paid',
}

/**
 * Staff Enums - All enumeration types for staff management
 */

import { Timestamp } from 'firebase/firestore';

// Department Enums
export enum Department {
  MANAGEMENT = 'management',
  PROJECT_MANAGEMENT = 'project_management',
  FIELD_OPERATIONS = 'field_operations',
  NETWORK_OPERATIONS = 'network_operations',
  ENGINEERING = 'engineering',
  INSTALLATION = 'installation',
  MAINTENANCE = 'maintenance',
  QUALITY_ASSURANCE = 'quality_assurance',
  TECHNICAL_SUPPORT = 'technical_support',
  SALES = 'sales',
  CUSTOMER_SERVICE = 'customer_service',
  LOGISTICS = 'logistics',
  ADMINISTRATION = 'administration',
  FINANCE = 'finance',
  HR = 'hr',
  IT = 'it',
  SAFETY = 'safety',
}

// Position enum for standardized roles
export enum Position {
