/**
 * VLM Construction Service
 *
 * AI-powered photo validation for construction QA using Qwen3-VL on Velocity:8100.
 * Evaluates photos per checklist step and returns structured results.
 *
 * Pattern: OpenAI-compatible chat/completions API with image_url messages.
 */

import { neon } from '@/lib/db-neon';
import { log } from '@/lib/logger';
import { getChecklist } from '../types/construction.types';
import type { Discipline, VlmStepResult, VlmOverallResult } from '../types';
import { recordCorrectExtraction, getVlmFewShotExamples, buildVlmFewShotPrompt } from '@/services/vlmLearningService';

const sql = neon(process.env.DATABASE_URL!);
const MODULE = 'cqa-vlm';
const VLM_URL = process.env.VLM_SERVICE_URL || 'http://100.96.203.105:8100';
const VLM_MODEL = 'Qwen3-VL-8B-Instruct';
const MAX_IMAGE_DIM = 1024;

interface ValidateOptions {
  reviewId: string;
  discipline: Discipline;
  photoId?: string;
  forceRerun?: boolean;
}

interface ValidateResult {
  photosProcessed: number;
  overallConfidence: number | null;
  vlmStatus: string;
  stepResults: VlmStepResult[];
  error?: string;
}

/**
 * Run VLM validation on a review's photos.
 * Updates construction_qa_reviews and construction_qa_photos with results.
 */
export async function validateReviewPhotos(opts: ValidateOptions): Promise<ValidateResult> {
  const { reviewId, discipline, photoId, forceRerun = false } = opts;
  const result: ValidateResult = {
    photosProcessed: 0,
    overallConfidence: null,
    vlmStatus: 'processing',
    stepResults: [],
  };

  try {
    // Mark review as processing
    await sql`
      UPDATE construction_qa_reviews
      SET vlm_status = 'processing', updated_at = NOW()
      WHERE id = ${reviewId}::uuid
    `;

    // Log activity
    await sql`
      INSERT INTO construction_qa_activity (review_id, event_type, actor, payload)
      VALUES (${reviewId}::uuid, 'vlm_started', 'vlm', '{}'::jsonb)
    `;

    // Fetch photos to validate
    let photosQuery = `
      SELECT id, storage_key, source, checklist_step, filename
      FROM construction_qa_photos
      WHERE review_id = $1::uuid
    `;
    const params: (string | boolean)[] = [reviewId];

    if (photoId) {
      photosQuery += ` AND id = $2::uuid`;
      params.push(photoId);
    } else if (!forceRerun) {
      photosQuery += ` AND vlm_processed_at IS NULL`;
    }

    photosQuery += ` ORDER BY checklist_step ASC NULLS LAST`;

    const photos = await sql.query(photosQuery, params);

    if (photos.length === 0) {
      result.vlmStatus = 'completed';
      await sql`
        UPDATE construction_qa_reviews
        SET vlm_status = 'completed', updated_at = NOW()
        WHERE id = ${reviewId}::uuid
      `;
      return result;
    }

    const checklist = getChecklist(discipline);

    // Fetch few-shot correction examples for prompt enhancement (non-blocking on failure)
    let fewShotSection = '';
    try {
      const fewShotExamples = await getVlmFewShotExamples({
        module: 'construction_qa',
        analysisType: 'construction_photo_qa',
        context: { discipline },
        maxExamples: 3,
        prioritizeCanonical: true,
      });
      fewShotSection = buildVlmFewShotPrompt(fewShotExamples, 'markdown');
    } catch (fewShotErr) {
      log.warn('Few-shot retrieval failed, continuing without', {
        error: (fewShotErr as Error).message,
      }, MODULE);
    }

    // Process each photo
    for (const photo of photos) {
      try {
        const step = photo.checklist_step;
        const stepDef = step ? checklist.find(s => s.step === step) : null;

        // Build the prompt for this photo
        const prompt = buildPhotoPrompt(discipline, step, stepDef ?? null, fewShotSection);

        // Build the photo URL for VLM
        const photoUrl = buildPhotoUrl(photo.storage_key, photo.source);

        // Call VLM
        const vlmResult = await callVlm(photoUrl, prompt, step || 0, stepDef?.label || 'Uncategorized');

        // Update photo with results
        await sql`
          UPDATE construction_qa_photos
          SET vlm_valid = ${vlmResult.valid},
              vlm_confidence = ${vlmResult.confidence},
              vlm_issues = ${JSON.stringify(vlmResult.issues)}::jsonb,
              vlm_feedback = ${vlmResult.feedback},
              vlm_raw = ${JSON.stringify(vlmResult)}::jsonb,
              vlm_processed_at = NOW(),
              updated_at = NOW()
          WHERE id = ${photo.id}::uuid
        `;

        result.stepResults.push(vlmResult);
        result.photosProcessed++;

        // Record VLM learning metric (fire-and-forget)
        if (vlmResult.confidence >= 0.7) {
          recordCorrectExtraction('construction_qa', 'construction_photo_qa', vlmResult.confidence)
            .catch(() => {});
        }
      } catch (photoErr) {
        log.error('Photo VLM failed', { photoId: photo.id, error: (photoErr as Error).message }, MODULE);
      }
    }

    // Calculate overall confidence
    if (result.stepResults.length > 0) {
      const totalConf = result.stepResults.reduce((sum, r) => sum + r.confidence, 0);
      result.overallConfidence = Number((totalConf / result.stepResults.length).toFixed(3));
    }

    // Build overall result
    const overallResult: VlmOverallResult = {
      overall_valid: result.stepResults.every(r => r.valid),
      overall_confidence: result.overallConfidence || 0,
      steps: Object.fromEntries(result.stepResults.map(r => [String(r.step), r])),
      cross_step_issues: [],
      processed_at: new Date().toISOString(),
      model_version: VLM_MODEL,
    };

    // Build step scores
    const stepScores: Record<string, number> = {};
    for (const sr of result.stepResults) {
      stepScores[`step_${String(sr.step).padStart(2, '0')}`] = sr.confidence;
    }

    // Update review with aggregate results
    result.vlmStatus = 'completed';
    await sql`
      UPDATE construction_qa_reviews
      SET vlm_status = 'completed',
          vlm_confidence = ${result.overallConfidence},
          vlm_step_scores = ${JSON.stringify(stepScores)}::jsonb,
          vlm_issues = ${JSON.stringify(overallResult.cross_step_issues)}::jsonb,
          vlm_raw_response = ${JSON.stringify(overallResult)}::jsonb,
          vlm_processed_at = NOW(),
          vlm_model_version = ${VLM_MODEL},
          updated_at = NOW()
      WHERE id = ${reviewId}::uuid
    `;

    // Log completion
    await sql`
      INSERT INTO construction_qa_activity (review_id, event_type, actor, payload)
      VALUES (${reviewId}::uuid, 'vlm_completed', 'vlm',
        ${JSON.stringify({ photos_processed: result.photosProcessed, overall_confidence: result.overallConfidence })}::jsonb)
    `;

    return result;
  } catch (err) {
    result.vlmStatus = 'failed';
    result.error = (err as Error).message;

    // Mark as failed
    await sql`
      UPDATE construction_qa_reviews
      SET vlm_status = 'failed',
          vlm_retry_count = vlm_retry_count + 1,
          updated_at = NOW()
      WHERE id = ${reviewId}::uuid
    `.catch((e) => log.warn('DB operation failed (non-critical)', { error: e instanceof Error ? e.message : 'unknown' }, MODULE));

    await sql`
      INSERT INTO construction_qa_activity (review_id, event_type, actor, payload)
      VALUES (${reviewId}::uuid, 'vlm_failed', 'vlm',
        ${JSON.stringify({ error: result.error })}::jsonb)
    `.catch((e) => log.warn('DB operation failed (non-critical)', { error: e instanceof Error ? e.message : 'unknown' }, MODULE));

    log.error('VLM validation failed', { reviewId, error: result.error }, MODULE);
    return result;
  }
}

/**
 * Call the VLM API with a photo and prompt.
 */
async function callVlm(
  imageUrl: string,
  prompt: string,
  step: number,
  stepLabel: string,
): Promise<VlmStepResult> {
  try {
    const response = await fetch(`${VLM_URL}/v1/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: VLM_MODEL,
        messages: [
          {
            role: 'user',
            content: [
              { type: 'image_url', image_url: { url: imageUrl, detail: 'high' } },
              { type: 'text', text: prompt },
            ],
          },
        ],
        max_tokens: 1024,
        temperature: 0.1,
      }),
    });

    if (!response.ok) {
      throw new Error(`VLM HTTP ${response.status}: ${await response.text()}`);
    }

    const data = await response.json();
    const text = data.choices?.[0]?.message?.content || '';

    // Parse structured JSON from VLM response
    return parseVlmResponse(text, step, stepLabel);
  } catch (err) {
    log.error('VLM call failed', { error: (err as Error).message }, MODULE);

    // Return a failure result
    return {
      valid: false,
      confidence: 0,
      step,
      step_label: stepLabel,
      issues: [`VLM error: ${(err as Error).message}`],
      feedback: 'AI validation unavailable — manual review required',
      extracted_data: {},
    };
  }
}

/**
 * Parse VLM text response into structured result.
 */
function parseVlmResponse(text: string, step: number, stepLabel: string): VlmStepResult {
  try {
    // Try to find JSON in the response
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      return {
        valid: Boolean(parsed.valid ?? parsed.pass ?? false),
        confidence: Number(parsed.confidence ?? parsed.score ?? 0) / (parsed.score != null && parsed.score > 1 ? 10 : 1),
        step,
        step_label: stepLabel,
        issues: Array.isArray(parsed.issues) ? parsed.issues : parsed.issue ? [parsed.issue] : [],
        feedback: parsed.feedback || parsed.comment || '',
        extracted_data: parsed.extracted_data || parsed.data || {},
      };
    }
  } catch {
    // JSON parse failed — fall through to text analysis
  }

  // Fallback: analyze text for pass/fail indicators
  const lower = text.toLowerCase();
  const valid = lower.includes('pass') || lower.includes('acceptable') || lower.includes('meets');
  const confidence = valid ? 0.7 : 0.3;

  return {
    valid,
    confidence,
    step,
    step_label: stepLabel,
    issues: valid ? [] : ['See VLM feedback for details'],
    feedback: text.slice(0, 500),
    extracted_data: {},
  };
}

/**
 * Build discipline-specific VLM prompt for a checklist step.
 */
function buildPhotoPrompt(
  discipline: Discipline,
  step: number | null,
  stepDef: { label: string; vlmCheck: string; notes?: string } | null,
  fewShotSection = '',
): string {
  const base = `You are a construction quality assurance AI inspector for fiber network installations.
Discipline: ${discipline}
${step ? `Checklist Step ${step}: ${stepDef?.label || 'Unknown'}` : 'General photo evaluation'}

${stepDef?.vlmCheck ? `Check: ${stepDef.vlmCheck}` : ''}
${stepDef?.notes ? `Notes: ${stepDef.notes}` : ''}
${fewShotSection ? `\n${fewShotSection}\n` : ''}
Evaluate this photo and respond with ONLY a JSON object:
{
  "valid": true/false,
  "confidence": 0.0-1.0,
  "issues": ["list of specific issues found"],
  "feedback": "one sentence of actionable feedback for the field technician",
  "extracted_data": { any relevant data extracted from the photo }
}

Be strict but fair. A photo must clearly show the required element to pass.`;

  return base;
}

/**
 * Build a URL for the VLM to access the photo.
 */
function buildPhotoUrl(storageKey: string, source: string): string {
  // VLM runs on Velocity, so we use the local API to proxy the photo
  const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || 'http://localhost:3004';
  return `${baseUrl}/api/construction-qa/photo-proxy?key=${encodeURIComponent(storageKey)}&source=${source}`;
}

/**
 * Construction QA Review API
 *
 * GET  /api/construction-qa/review?id={reviewId}
 *   - Returns full review detail with photos and activity
 *
 * POST /api/construction-qa/review
 *   - Updates review checklist steps and extracted data (Phase 2/3)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth, withPermission } from '@/lib/auth/middleware';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') return handleGet(req, res);
  if (req.method === 'POST') return handlePost(req, res);
  return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['GET', 'POST']);
}

async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const { id } = req.query;

  if (!id || typeof id !== 'string') {
    return apiResponse.badRequest(res, 'Review id is required');
  }

  try {
    // Fetch review with project name
    const reviews = await sql`
      SELECT
        r.*,
        p.project_name
      FROM construction_qa_reviews r
      JOIN projects p ON p.id = r.project_id
      WHERE r.id = ${id}::uuid
      LIMIT 1
    `;

    if (reviews.length === 0) {
      return apiResponse.notFound(res, 'Review', id);
    }

    const review = reviews[0];

    // Fetch photos
    const photos = await sql`
      SELECT *
      FROM construction_qa_photos
      WHERE review_id = ${id}::uuid
      ORDER BY checklist_step ASC NULLS LAST, created_at ASC
    `;

    // Fetch recent activity (last 50 entries)
    const activity = await sql`
      SELECT *
      FROM construction_qa_activity
      WHERE review_id = ${id}::uuid
      ORDER BY created_at DESC
      LIMIT 50
    `;

    return apiResponse.success(res, {
      review,
      photos,
      activity,
    });
  } catch (error) {
    log.error('Review GET error', { module: 'construction-qa', error: (error as Error).message });

    if ((error as Error).message?.includes('does not exist')) {
      return apiResponse.success(res, { review: null, photos: [], activity: [] });
    }

    return apiResponse.internalError(res, error);
  }
}

async function handlePost(req: NextApiRequest, res: NextApiResponse) {
  try {
    const { reviewId, stepUpdates, extractedDataUpdates, notes, reviewedBy, featureIdUpdate } = req.body;

    if (!reviewId) {
      return apiResponse.badRequest(res, 'reviewId is required');
    }

    // Build SET clauses from step updates
    const setClauses: string[] = ['updated_at = NOW()'];
    const params: (string | number | boolean)[] = [reviewId];
    let paramIdx = 2;

    // Valid step column names (whitelist to prevent SQL injection)
    const validStepColumns = new Set([
      // Civil — Pole Install Capture Checklist (8 steps)
      'civil_step_01_before_photo', 'civil_step_02_during_photo', 'civil_step_03_depth_photo',
      'civil_step_04_end_plates', 'civil_step_05_compaction', 'civil_step_06_level_check',
      'civil_step_07_after_photo', 'civil_step_08_signature',
      // Optical — Phase A / Distribution Dome (steps 1-8)
      'optical_step_01_dome_on_pole', 'optical_step_02_dome_label',
      'optical_step_03_open_dome', 'optical_step_04_splice_protectors',
      'optical_step_05_slack_management', 'optical_step_06_strength_members',
      'optical_step_07_seals_dustcaps', 'optical_step_08_pole_id',
      // Optical — Phase B / Main Joint (steps 11-16)
      'optical_step_11_cable_entries', 'optical_step_12_strength_members',
      'optical_step_13_tube_routing', 'optical_step_14_tray_entries',
      'optical_step_15_coiling_protectors', 'optical_step_16_readable_labels',
    ]);

    const updatedFields: string[] = [];

    if (stepUpdates && typeof stepUpdates === 'object') {
      for (const [col, val] of Object.entries(stepUpdates)) {
        if (validStepColumns.has(col)) {
          setClauses.push(`${col} = $${paramIdx}`);
          params.push(Boolean(val));
          paramIdx++;
          updatedFields.push(col);
        }
      }
    }

    // Valid extracted data columns
    const validExtractedColumns = new Set([
      'extracted_pole_number', 'extracted_pole_height', 'extracted_cable_type',
      'extracted_joint_type', 'extracted_splice_count',
    ]);

    if (extractedDataUpdates && typeof extractedDataUpdates === 'object') {
      for (const [col, val] of Object.entries(extractedDataUpdates)) {
        if (validExtractedColumns.has(col)) {
          setClauses.push(`${col} = $${paramIdx}`);
          params.push(val as string | number);
          paramIdx++;
          updatedFields.push(col);
        }
      }
    }

    if (notes) {
      setClauses.push(`qa_notes = $${paramIdx}`);
      params.push(notes);
      paramIdx++;
      updatedFields.push('qa_notes');
    }

    // Feature ID rename/reassign
    if (featureIdUpdate && typeof featureIdUpdate === 'string') {
      setClauses.push(`feature_id = $${paramIdx}`);
      params.push(featureIdUpdate.trim());
      paramIdx++;
      updatedFields.push('feature_id');

      // If renaming to a valid pole pattern, try to backfill zone/PON and clear unidentified
      const validPolePattern = /^[A-Z]{3}\.P\./;
      if (validPolePattern.test(featureIdUpdate.trim())) {
        setClauses.push(`workflow_status = CASE WHEN workflow_status = 'unidentified' THEN 'pending' ELSE workflow_status END`);
      }
    }

    // Move to in_review if currently pending
    setClauses.push(`workflow_status = CASE WHEN workflow_status = 'pending' THEN 'in_review' ELSE workflow_status END`);

    // Execute update
    const updateQuery = `
      UPDATE construction_qa_reviews
      SET ${setClauses.join(', ')}
      WHERE id = $1::uuid
      RETURNING id
    `;

    const result = await sql.query(updateQuery, params);

    if (result.length === 0) {
      return apiResponse.notFound(res, 'Review', reviewId);
    }

    // Log activity
    if (updatedFields.length > 0) {
      const eventType = updatedFields.includes('feature_id') ? 'comment_added' : 'step_checked';
      const payload = updatedFields.includes('feature_id')
        ? { action: 'feature_id_renamed', new_feature_id: featureIdUpdate, updated_fields: updatedFields }
        : { updated_fields: updatedFields };

      await sql`
        INSERT INTO construction_qa_activity (review_id, event_type, actor, payload)
        VALUES (
          ${reviewId}::uuid,
          ${eventType},
          ${reviewedBy || 'unknown'},
          ${JSON.stringify(payload)}::jsonb
        )
      `;
    }

    return apiResponse.success(res, {
      reviewId,
      updatedFields,
    });
  } catch (error) {
    log.error('Review POST error', { module: 'construction-qa', error: (error as Error).message });
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(withPermission('construction-qa.qa-centre')(handler));

/**
 * Field Ops Photo Processing Service
 *
 * Handles downloading WhatsApp construction photos from the bridge and staging
 * them for Firebase upload. Processes photos from field_ops_wa_photos table
 * with pending upload_status.
 *
 * Flow:
 * 1. Query pending photos from field_ops_wa_photos
 * 2. Request download from WhatsApp bridge /api/download
 * 3. Stage file locally and record intended Firebase storage path
 * 4. Update status to 'uploaded' with storage_key
 *
 * @module field-ops/services/fieldOpsPhotoService
 */

import { neon } from '@/lib/db-neon';
import { createLogger } from '@/lib/logger';
import fs from 'fs';

const logger = createLogger('fieldOpsPhotoService');

// ============================================================================
// Configuration
// ============================================================================

const WA_BRIDGE_DOWNLOAD_URL =
  process.env.WA_BRIDGE_URL || 'http://72.61.197.178:8083/api/download';

// ============================================================================
// Database Connection
// ============================================================================

function getDb() {
  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    throw new Error('DATABASE_URL environment variable is not set');
  }
  return neon(databaseUrl);
}

// ============================================================================
// Types
// ============================================================================

interface PendingPhoto {
  id: string;
  message_id: string;
  wa_media_id: string;
  wa_group_jid: string;
  group_type: string;
  project: string;
  sender_name: string;
  message_timestamp: string;
  mime_type: string;
  wa_message_id: string;
}

interface DownloadResult {
  success: boolean;
  filename?: string;
  path?: string;
  error?: string;
}

interface FirebaseStageResult {
  success: boolean;
  storageKey?: string;
  error?: string;
}

// ============================================================================
// WhatsApp Bridge Media Download
// ============================================================================

/**
 * Download media from WhatsApp bridge
 */
async function downloadFromBridge(
  messageId: string,
  chatJid: string
): Promise<DownloadResult> {
  try {
    const response = await fetch(WA_BRIDGE_DOWNLOAD_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        message_id: messageId,
        chat_jid: chatJid,
      }),
    });

    const result = await response.json();

    if (result.success && result.path) {
      return {
        success: true,
        filename: result.filename,
        path: result.path,
      };
    }

    return {
      success: false,
      error: result.message || 'Unknown download error',
    };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Download failed',
    };
  }
}

// ============================================================================
// Firebase Storage Staging
// ============================================================================

/**
 * Stage photo for Firebase upload.
 * Records the intended Firebase storage path; the file is already local from the bridge.
 * Actual Firebase upload runs in a background job when credentials are configured.
 */
async function stageForFirebase(
  localPath: string,
  storagePath: string
): Promise<FirebaseStageResult> {
  try {
    if (!fs.existsSync(localPath)) {
      return { success: false, error: `Local file not found: ${localPath}` };
    }

    logger.info('Photo staged for Firebase upload', { localPath, storagePath });
    return { success: true, storageKey: storagePath };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Staging failed',
    };
  }
}

// ============================================================================
// Photo Processing
// ============================================================================

/**
 * Get pending photos that need downloading and uploading
 */
export async function getPendingPhotos(limit = 10): Promise<PendingPhoto[]> {
  const sql = getDb();

  const result = await sql`
    SELECT
      p.id,
      p.message_id,
      p.wa_media_id,
      p.wa_group_jid,
      p.group_type,
      p.project,
      p.sender_name,
      p.message_timestamp,
      p.mime_type,
      m.wa_message_id
    FROM field_ops_wa_photos p
    JOIN field_ops_wa_messages m ON p.message_id = m.id
    WHERE p.upload_status = 'pending'
    ORDER BY p.created_at ASC
    LIMIT ${limit}
  `;

  return result as unknown as PendingPhoto[];
}

/**
 * Process a single pending photo: download from bridge + stage for Firebase
 */
export async function processPhoto(
  photo: PendingPhoto
): Promise<{ success: boolean; error?: string }> {
  const sql = getDb();

  // Mark as uploading
  await sql`
    UPDATE field_ops_wa_photos
    SET upload_status = 'uploading', updated_at = NOW()
    WHERE id = ${photo.id}
  `;

  // Step 1: Download from WhatsApp bridge
  logger.info('Downloading photo from bridge', {
    photoId: photo.id,
    messageId: photo.wa_message_id,
  });

  const download = await downloadFromBridge(photo.wa_message_id, photo.wa_group_jid);

  if (!download.success || !download.path) {
    await sql`
      UPDATE field_ops_wa_photos
      SET upload_status = 'failed', upload_error = ${download.error || null}, updated_at = NOW()
      WHERE id = ${photo.id}
    `;
    return { success: false, error: download.error };
  }

  // Step 2: Stage for Firebase
  const date = new Date(photo.message_timestamp).toISOString().split('T')[0];
  const filename = download.filename || `photo_${photo.id}.jpg`;
  const storagePath = `construction-qa/${photo.project}/${date}/${filename}`;

  const stage = await stageForFirebase(download.path, storagePath);

  if (!stage.success) {
    await sql`
      UPDATE field_ops_wa_photos
      SET upload_status = 'failed', upload_error = ${stage.error || null}, updated_at = NOW()
      WHERE id = ${photo.id}
    `;
    return { success: false, error: stage.error };
  }

  // Step 3: Update to uploaded with storage key and local path
  await sql`
    UPDATE field_ops_wa_photos
    SET
      upload_status = 'uploaded',
      storage_key = ${stage.storageKey || null},
      local_path = ${download.path},
      uploaded_at = NOW(),
      updated_at = NOW()
    WHERE id = ${photo.id}
  `;

  logger.info('Photo staged successfully', {
    photoId: photo.id,
    storageKey: stage.storageKey,
  });

  return { success: true };
}

/**
 * Batch process pending photos (download + stage)
 */
export async function processPendingPhotos(limit = 10): Promise<{
  processed: number;
  succeeded: number;
  failed: number;
  errors: string[];
}> {
  const pendingPhotos = await getPendingPhotos(limit);

  const results = {
    processed: 0,
    succeeded: 0,
    failed: 0,
    errors: [] as string[],
  };

  for (const photo of pendingPhotos) {
    results.processed++;

    try {
      const result = await processPhoto(photo);

      if (result.success) {
        results.succeeded++;
      } else {
        results.failed++;
        results.errors.push(`Photo ${photo.id}: ${result.error}`);
      }
    } catch (error) {
      results.failed++;
      results.errors.push(
        `Photo ${photo.id}: ${error instanceof Error ? error.message : 'Unknown error'}`
      );
    }
  }

  logger.info('Batch photo processing complete', {
    processed: results.processed,
    succeeded: results.succeeded,
    failed: results.failed,
  });

  return results;
}

/**
 * Construction QA Module — TypeScript Type Definitions
 *
 * Covers the two pre-activation construction disciplines:
 *   • Civil      — pole planting
 *   • Optical    — dome joint installation (Phase A: distribution dome, Phase B: main joint)
 *
 * Database alignment: construction_qa_reviews, construction_qa_photos,
 *   construction_qa_activity, construction_qa_assignments (migrations 200–203, 240).
