 */

import { vfStorage } from '@/services/vfStorageAdapter';
import { query, queryOne } from '../utils/db';
import { createLogger } from '@/lib/logger';
import {
  TicketAttachment,
  CreateAttachmentPayload,
  UpdateAttachmentPayload,
  FileUploadRequest,
  FileUploadResult,
