#!/usr/bin/env node
/**
 * Session State Tracker Hook
 *
 * Automatically updates .claude/session/current.json after significant actions.
 *
 * Hook Type: PostToolUse
 *
 * Tracks:
 * - Files modified (Edit, Write)
 * - Commands executed (Bash with deployments, migrations, git)
 * - Progress milestones
 */

const fs = require('fs');
const path = require('path');

const SESSION_FILE = path.join(process.cwd(), '.claude', 'session', 'current.json');

// Patterns that indicate significant actions worth tracking
const SIGNIFICANT_PATTERNS = {
  deployment: /deploy|staging|production|fibreflow\.service|systemctl restart/i,
  migration: /migration|migrate|\.sql/i,
  git: /git (push|commit|merge)/i,
  service: /systemctl|restart|service/i,
  test: /npm test|vitest|jest/i,
  build: /npm run build|next build/i,
};

function loadSession() {
  try {
    if (fs.existsSync(SESSION_FILE)) {
      return JSON.parse(fs.readFileSync(SESSION_FILE, 'utf8'));
    }
  } catch (e) {
    // Ignore parse errors
  }

  // Return default session structure
  return {
    session_id: `session-${Date.now()}`,
    started_at: new Date().toISOString(),
    last_updated: new Date().toISOString(),
    working_on: {
      task: 'Unknown task',
      status: 'in_progress',
      progress: [],
      files_modified: [],
      last_action: null
    },
    pending_tasks: [],
    context: {}
  };
}

function saveSession(session) {
  session.last_updated = new Date().toISOString();

  const sessionDir = path.dirname(SESSION_FILE);
  if (!fs.existsSync(sessionDir)) {
    fs.mkdirSync(sessionDir, { recursive: true });
  }

  fs.writeFileSync(SESSION_FILE, JSON.stringify(session, null, 2));
}

function getActionType(toolName, toolInput) {
  if (toolName === 'Edit' || toolName === 'Write') {
    return 'file_change';
  }

  if (toolName === 'Bash') {
    for (const [type, pattern] of Object.entries(SIGNIFICANT_PATTERNS)) {
      if (pattern.test(toolInput)) {
        return type;
      }
    }
    return 'command';
  }

  return 'other';
}

function extractFilePath(toolInput) {
  const match = toolInput.match(/"file_path":\s*"([^"]+)"/);
  return match ? match[1] : null;
}

function extractCommand(toolInput) {
  const match = toolInput.match(/"command":\s*"([^"]+)"/);
  return match ? match[1].substring(0, 100) : null;
}

function formatProgress(actionType, details) {
  const timestamp = new Date().toLocaleTimeString('en-ZA', { hour: '2-digit', minute: '2-digit' });
  const icons = {
    file_change: '📝',
    deployment: '🚀',
    migration: '🗃️',
    git: '📦',
    service: '⚙️',
    test: '🧪',
    build: '🔨',
    command: '💻',
    other: '•'
  };

  return `${icons[actionType] || '•'} [${timestamp}] ${details}`;
}

function main() {
  const toolName = process.env.TOOL_NAME || '';
  const toolInput = process.env.TOOL_INPUT || '';

  // Only track significant tools
  const trackableTools = ['Edit', 'Write', 'Bash'];
  if (!trackableTools.includes(toolName)) {
    return;
  }

  const actionType = getActionType(toolName, toolInput);

  // Skip non-significant commands
  if (actionType === 'command' || actionType === 'other') {
    return;
  }

  const session = loadSession();

  // Track file modifications
  if (toolName === 'Edit' || toolName === 'Write') {
    const filePath = extractFilePath(toolInput);
    if (filePath) {
      // Store relative path
      const relativePath = filePath.replace(process.cwd() + '/', '');

      if (!session.working_on.files_modified.includes(relativePath)) {
        session.working_on.files_modified.push(relativePath);

        // Keep only last 20 files
        if (session.working_on.files_modified.length > 20) {
          session.working_on.files_modified = session.working_on.files_modified.slice(-20);
        }
      }

      session.working_on.last_action = `Modified ${path.basename(filePath)}`;

      // Add to progress for significant files
      if (relativePath.includes('service') || relativePath.includes('api/') || relativePath.includes('.claude/')) {
        const progress = formatProgress('file_change', `Modified ${relativePath}`);
        session.working_on.progress.push(progress);
      }
    }
  }

  // Track significant bash commands
  if (toolName === 'Bash' && actionType !== 'command') {
    const command = extractCommand(toolInput);
    const details = {
      deployment: 'Deployment action',
      migration: 'Database migration',
      git: 'Git operation',
      service: 'Service operation',
      test: 'Running tests',
      build: 'Building project'
    }[actionType] || command;

    session.working_on.last_action = details;

    const progress = formatProgress(actionType, details);
    session.working_on.progress.push(progress);
  }

  // Keep only last 50 progress entries
  if (session.working_on.progress.length > 50) {
    session.working_on.progress = session.working_on.progress.slice(-50);
  }

  saveSession(session);
}

main();

#!/usr/bin/env node
/**
 * Session Recovery Hook
 *
 * Triggered on SessionStart to check for previous session state
 * and provide recovery information to Claude.
 *
 * Usage in settings.json:
 * {
 *   "hooks": {
 *     "SessionStart": ["node .claude/hooks/session-recovery.js"]
 *   }
 * }
 */

const fs = require('fs');
const path = require('path');

const SESSION_FILE = path.join(__dirname, '..', 'session', 'current.json');
const HISTORY_DIR = path.join(__dirname, '..', 'session', 'history');

function formatTimestamp(isoString) {
  const date = new Date(isoString);
  return date.toLocaleString('en-ZA', {
    dateStyle: 'medium',
    timeStyle: 'short'
  });
}

function getTimeSince(isoString) {
  const then = new Date(isoString);
  const now = new Date();
  const diffMs = now - then;
  const diffMins = Math.floor(diffMs / 60000);
  const diffHours = Math.floor(diffMins / 60);
  const diffDays = Math.floor(diffHours / 24);

  if (diffDays > 0) return `${diffDays} day(s) ago`;
  if (diffHours > 0) return `${diffHours} hour(s) ago`;
  if (diffMins > 0) return `${diffMins} minute(s) ago`;
  return 'just now';
}

function main() {
  // Check if session file exists
  if (!fs.existsSync(SESSION_FILE)) {
    console.log('No previous session found. Starting fresh.');
    return;
  }

  try {
    const session = JSON.parse(fs.readFileSync(SESSION_FILE, 'utf8'));

    // Build recovery message
    const lines = [
      '',
      '╔══════════════════════════════════════════════════════════════╗',
      '║                   SESSION RECOVERY AVAILABLE                  ║',
      '╠══════════════════════════════════════════════════════════════╣',
    ];

    // Last session info
    if (session.last_updated) {
      lines.push(`║ Last active: ${formatTimestamp(session.last_updated).padEnd(42)}║`);
      lines.push(`║ Time since:  ${getTimeSince(session.last_updated).padEnd(42)}║`);
    }

    // Current task
    if (session.working_on) {
      lines.push('╠══════════════════════════════════════════════════════════════╣');
      lines.push('║ LAST TASK:                                                   ║');
      const task = session.working_on.task || 'Unknown';
      lines.push(`║   ${task.substring(0, 54).padEnd(54)}║`);

      if (session.working_on.status) {
        lines.push(`║   Status: ${session.working_on.status.padEnd(47)}║`);
      }

      if (session.working_on.last_action) {
        lines.push('║                                                              ║');
        lines.push('║ LAST ACTION:                                                 ║');
        const action = session.working_on.last_action.substring(0, 54);
        lines.push(`║   ${action.padEnd(54)}║`);
      }
    }

    // Progress checkpoints
    if (session.working_on?.progress?.length > 0) {
      lines.push('╠══════════════════════════════════════════════════════════════╣');
      lines.push('║ PROGRESS:                                                    ║');
      session.working_on.progress.slice(-5).forEach(item => {
        const trimmed = item.substring(0, 56);
        lines.push(`║   ${trimmed.padEnd(54)}║`);
      });
    }

    // Pending tasks
    if (session.pending_tasks?.length > 0) {
      lines.push('╠══════════════════════════════════════════════════════════════╣');
      lines.push('║ PENDING TASKS:                                               ║');
      session.pending_tasks.slice(0, 3).forEach(task => {
        const desc = typeof task === 'string' ? task : task.description;
        const trimmed = desc.substring(0, 54);
        lines.push(`║   • ${trimmed.padEnd(52)}║`);
      });
      if (session.pending_tasks.length > 3) {
        lines.push(`║   ... and ${(session.pending_tasks.length - 3)} more`.padEnd(59) + '║');
      }
    }

    // Files modified
    if (session.working_on?.files_modified?.length > 0) {
      lines.push('╠══════════════════════════════════════════════════════════════╣');
      lines.push('║ FILES MODIFIED:                                              ║');
      session.working_on.files_modified.slice(0, 3).forEach(file => {
        const trimmed = file.substring(0, 54);
        lines.push(`║   ${trimmed.padEnd(54)}║`);
      });
    }

    // Previous session summary
    if (session.previous_session?.summary) {
      lines.push('╠══════════════════════════════════════════════════════════════╣');
      lines.push('║ PREVIOUS SESSION:                                            ║');
      const summary = session.previous_session.summary.substring(0, 54);
      lines.push(`║   ${summary.padEnd(54)}║`);
    }

    lines.push('╠══════════════════════════════════════════════════════════════╣');
    lines.push('║ To continue where you left off, say "continue" or "resume"   ║');
    lines.push('║ To start fresh, say "new session" or just describe your task ║');
    lines.push('╚══════════════════════════════════════════════════════════════╝');
    lines.push('');

    console.log(lines.join('\n'));

  } catch (error) {
    console.error('Error reading session file:', error.message);
  }
}

main();
